insert into public.lessons (id, topic_id, position, title, usage_text, formula, signals_text)
select x.* from jsonb_to_recordset($seed$
[
{"id":"chuyen-de-thi-dong-tu/theory/0","topic_id":"chuyen-de-thi-dong-tu","position":0,"title":"Thì hiện tại đơn","usage_text":"- diễn tả hành động thường xuyên xảy ra.\n- diễn tả thói quen.\n- diễn tả thời gian biểu, lịch trình, thông báo.\n- diễn tả sự thật, chân lí.\n- diễn tả nghề nghiệp, sở thích, nguồn gốc, bình phẩm.","formula":{"has_be":true,"ordinary":{"affirmative":"S + V(s/es) + O","negative":"S + do / does + not + V(bare) + O","interrogative":"Do / Does + S + V(bare) + O?"},"be":{"affirmative":"S + am / is / are + Noun/Adj","negative":"S + am / is / are + not + Noun/Adj","interrogative":"Am / Is / Are + S + Noun/Adj?"},"notes":["Chủ ngữ số ít (He, She, It, Danh từ số ít) đi với V(s/es), 'is', hoặc trợ động từ 'does'.","Chủ ngữ số nhiều (We, You, They, Danh từ số nhiều) đi với V(bare), 'are', hoặc trợ động từ 'do'.","Chủ ngữ 'I' đi với V(bare), 'am', hoặc trợ động từ 'do'.","Khi đã mượn trợ động từ do/does, động từ chính luôn ở dạng nguyên mẫu V(bare)."]},"signals_text":"- seldom/ rarely/ hardly\n- sometimes/ occasionally\n- often/ usually/ frequently\n- always/ constantly\n- ever\n- never\n- every"},
{"id":"chuyen-de-thi-dong-tu/theory/1","topic_id":"chuyen-de-thi-dong-tu","position":1,"title":"Thì quá khứ đơn","usage_text":"- diễn tả hành động đã xảy ra và đã chấm dứt trong quá khứ, không còn liên quan tới hiện tại.\n- diễn tả hành động xảy ra nối tiếp nhau trong quá khứ.\n- diễn tả hồi ức, kỉ niệm.","formula":{"has_be":true,"ordinary":{"affirmative":"S + V2/ed + O","negative":"S + did + not + V(bare) + O","interrogative":"Did + S + V(bare) + O?"},"be":{"affirmative":"S + was / were + Noun/Adj","negative":"S + was / were + not + Noun/Adj","interrogative":"Was / Were + S + Noun/Adj?"},"notes":["Chủ ngữ số ít & I (I, He, She, It, Danh từ số ít) đi với 'was'.","Chủ ngữ số nhiều (We, You, They, Danh từ số nhiều) đi với 'were'.","Trợ động từ 'did' dùng chung cho tất cả các chủ ngữ ở thể phủ định và nghi vấn.","Khi đã dùng trợ động từ did, động từ chính quay về dạng nguyên mẫu V(bare)."]},"signals_text":"- ago\n- last\n- yesterday\n- in + một mốc thời gian trong quá khứ (in 2000...)"},
{"id":"chuyen-de-thi-dong-tu/theory/2","topic_id":"chuyen-de-thi-dong-tu","position":2,"title":"Thì tương tai đơn","usage_text":"- diễn tả những hành động sẽ xảy ra trong tương lai.\n- diễn tả những dự đoán.\n- diễn tả lời hứa.","formula":{"has_be":false,"ordinary":{"affirmative":"S + will + V(bare) + O","negative":"S + will + not (won't) + V(bare) + O","interrogative":"Will + S + V(bare) + O?"},"notes":["Dùng trợ động từ 'will' (hoặc viết tắt 'll') cho tất cả các chủ ngữ.","Dạng phủ định viết tắt của 'will not' là 'won't'.","Động từ đi sau will/won't luôn ở dạng nguyên mẫu không 'to' V(bare)."]},"signals_text":"- tomorrow\n- next\n- soon\n- in + một khoảng thời gian (in an hour...)"},
{"id":"chuyen-de-thi-dong-tu/theory/3","topic_id":"chuyen-de-thi-dong-tu","position":3,"title":"Thì hiện tại tiếp diễn","usage_text":"- diễn tả hành động đang xảy ra tại thời điểm nói.\n- diễn tả hành động sẽ xảy ra trong tương lai (có kế hoạch từ trước).\n- diễn tả sự thay đổi của thói quen.\n- diễn ta sự ca thán, phàn nàn.","formula":{"has_be":false,"ordinary":{"affirmative":"S + am / is / are + V-ing + O","negative":"S + am / is / are + not + V-ing + O","interrogative":"Am / Is / Are + S + V-ing + O?"},"notes":["I + am + V-ing.","He, She, It, Danh từ số ít + is + V-ing.","We, You, They, Danh từ số nhiều + are + V-ing."]},"signals_text":"- now\n- at the moment\n- at present\n- right now\n- look /hear (!)"},
{"id":"chuyen-de-thi-dong-tu/theory/4","topic_id":"chuyen-de-thi-dong-tu","position":4,"title":"Thì quá khứ tiếp diễn","usage_text":"- diễn tả hành động đang xảy ra tại một thời điểm xác định trong quá khứ.\n- diễn tả hành động đang xảy ra thì có hành động khác xen vào, hành động nào xảy ra trước chia thì quá khử tiếp diễn, hành động nào xảy ra sau chia thì quá khứ đơn.","formula":{"has_be":false,"ordinary":{"affirmative":"S + was / were + V-ing + O","negative":"S + was / were + not + V-ing + O","interrogative":"Was / Were + S + V-ing + O?"},"notes":["I, He, She, It, Danh từ số ít + was + V-ing.","We, You, They, Danh từ số nhiều + were + V-ing."]},"signals_text":"- giờ + trạng từ quá khứ (at 3 pm yesterday...)\n- at this/that time + trạng từ quá khứ ( at this time last week....)"},
{"id":"chuyen-de-thi-dong-tu/theory/5","topic_id":"chuyen-de-thi-dong-tu","position":5,"title":"Thì tương tai tiếp diễn","usage_text":"- diễn tả hành động đang diễn ra vào một thời điểm cụ thể trong tương lai.\n- diễn tả hành động sẽ đang xảy ra trong tương lai thì có hành động khác xen vào, hành động nào xảy ra trước chia thì tương lai tiếp diễn, hành động nào xảy ra sau chia thì hiện tại đơn.","formula":{"has_be":false,"ordinary":{"affirmative":"S + will be + V-ing + O","negative":"S + will + not + be + V-ing + O","interrogative":"Will + S + be + V-ing + O?"},"notes":["Dùng cụm trợ động từ 'will be' cho tất cả các chủ ngữ.","Ở thể phủ định, từ 'not' đứng giữa 'will' và 'be' (will not be / won't be)."]},"signals_text":"- giờ + trạng từ tương lai (at 3 pm tomorrow...)\n- at this/that time + trạng từ tương lai\n(at this time next week....)"},
{"id":"chuyen-de-thi-dong-tu/theory/6","topic_id":"chuyen-de-thi-dong-tu","position":6,"title":"Thì hiện tại hoàn thành","usage_text":"- diễn tả hành động xảy ra trong quá khứ nhưng không rõ thời gian.\n- diễn tả hành động lặp đi lặp lại nhiều lần trong quá khứ.\n- diễn tả hành động xảy ra trong quá khứ nhưng để lại dấu hiệu hoặc hậu quả ở hiện tại.\n- diễn tả những trải nghiệm.\n- diễn tả những hành động xảy ra trong quá khứ nhưng kéo dài tới hiện tại và vẫn còn có khả năng sẽ tiếp diễn trong tương lai.","formula":{"has_be":false,"ordinary":{"affirmative":"S + have / has + V3/ed + O","negative":"S + have / has + not + V3/ed + O","interrogative":"Have / Has + S + V3/ed + O?"},"notes":["Chủ ngữ số ít (He, She, It, Danh từ số ít) đi với 'has'.","Chủ ngữ số nhiều & I (I, We, You, They, Danh từ số nhiều) đi với 'have'.","V3/ed là động từ thêm đuôi '-ed' (đối với động từ có quy tắc) hoặc động từ ở cột thứ 3 trong bảng động từ bất quy tắc."]},"signals_text":"- for\n- since\n- ever\n- never\n- so far\n- recently\n- lately\n- before (đứng cuối câu)\n- up to now/ up to present/ until now\n- yet\n- just\n- already"},
{"id":"chuyen-de-thi-dong-tu/theory/7","topic_id":"chuyen-de-thi-dong-tu","position":7,"title":"Thì quá khứ hoàn thành","usage_text":"- diễn tả những hành động xảy ra và hoàn thành trước hành động khác trong quá khứ.","formula":{"has_be":false,"ordinary":{"affirmative":"S + had + V3/ed + O","negative":"S + had + not + V3/ed + O","interrogative":"Had + S + V3/ed + O?"},"notes":["Trợ động từ 'had' dùng cho tất cả các chủ ngữ.","Ở thể phủ định có thể viết tắt thành 'hadn't'."]},"signals_text":"- before/by the time (trước chia quá khứ hoàn thành, sau chia quá khứ đơn).\n- after (trước chia quá khứ đơn, sau chia quá khứ hoàn thành).\n\u0011"},
{"id":"chuyen-de-thi-dong-tu/theory/8","topic_id":"chuyen-de-thi-dong-tu","position":8,"title":"Thì tương lai hoàn thành","usage_text":"- diễn tả hành động sẽ được hoàn thành trước khi một hành động khác xảy đến.","formula":{"has_be":false,"ordinary":{"affirmative":"S + will have + V3/ed + O","negative":"S + will + not + have + V3/ed + O","interrogative":"Will + S + have + V3/ed + O?"},"notes":["Dùng cụm trợ động từ 'will have' cho tất cả các chủ ngữ (không chia has).","Ở thể phủ định, từ 'not' đứng giữa 'will' và 'have' (will not have / won't have)."]},"signals_text":""},
{"id":"chuyen-de-thi-dong-tu/theory/9","topic_id":"chuyen-de-thi-dong-tu","position":9,"title":"Thì hiện tại hoàn thành tiếp diễn","usage_text":"- nhấn mạnh khoảng thời gian của một hành động đã xảy ra trong quá khứ và tiếp tục tới hiện tại (có thể tiếp diễn trong tương lai).","formula":{"has_be":false,"ordinary":{"affirmative":"S + have / has + been + V-ing + O","negative":"S + have / has + not + been + V-ing + O","interrogative":"Have / Has + S + been + V-ing + O?"},"notes":["Chủ ngữ số ít (He, She, It, Danh từ số ít) đi với 'has been'.","Chủ ngữ số nhiều & I (I, We, You, They, Danh từ số nhiều) đi với 'have been'.","Sử dụng khi muốn nhấn mạnh sự liên tục, kéo dài của hành động."]},"signals_text":"- all day/week....\n- almost every day this week...\n- in the past year..."},
{"id":"chuyen-de-thi-dong-tu/theory/10","topic_id":"chuyen-de-thi-dong-tu","position":10,"title":"Thì quá khứ hoàn thành tiếp diễn","usage_text":"nhấn mạnh khoảng thời gian của một hành động đã xảy ra trong quá khử và kết thúc trước một hành động quá khứ khác.","formula":{"has_be":false,"ordinary":{"affirmative":"S + had been + V-ing + O","negative":"S + had + not + been + V-ing + O","interrogative":"Had + S + been + V-ing + O?"},"notes":["Sử dụng cụm trợ động từ 'had been' cho tất cả các chủ ngữ.","Ở dạng phủ định viết tắt thành 'hadn't been'."]},"signals_text":"- until then\n- prior to that time"},
{"id":"chuyen-de-thi-dong-tu/theory/11","topic_id":"chuyen-de-thi-dong-tu","position":11,"title":"Thì tương lai hoàn thành tiếp diễn","usage_text":"nhấn mạnh khoảng thời gian của một hành động sẽ đang xảy ra trong tương lai và kết thúc trước một hành động tương lai khác.","formula":{"has_be":false,"ordinary":{"affirmative":"S + will have been + V-ing + O","negative":"S + will + not + have been + V-ing + O","interrogative":"Will + S + have been + V-ing + O?"},"notes":["Sử dụng cụm trợ động từ 'will have been' cho tất cả các chủ ngữ.","Dạng phủ định viết tắt là 'won't have been'."]},"signals_text":""},
{"id":"su-phoi-thi/theory/0","topic_id":"su-phoi-thi","position":0,"title":"Phối thì với WHEN","usage_text":"diễn tả mối quan hệ thời gian giữa các hành động bằng cách dùng liên từ WHEN.","formula":{"custom":true,"rules":[{"title":"Diễn tả hành động xảy ra nối tiếp nhau","past":"WHEN + S + V(quá khứ đơn) , S + V(quá khứ đơn)","past_eg":"When he saw me, he smiled at me.","future":"WHEN + S + V(hiện tại đơn) , S + V(tương lai đơn)","future_eg":"When I see him, I will remind him to call you."},{"title":"Diễn tả một hành động đang xảy ra thì có hành động khác xen vào","past":"WHEN + S + V(quá khứ đơn) , S + V(quá khứ tiếp diễn)","past_eg":"When I came to see her, she was cooking dinner.","future":"WHEN + S + V(hiện tại đơn) , S + V(tương lai tiếp diễn)","future_eg":"When you come in, your boss will be waiting for you there."},{"title":"Diễn tả một hành động xảy ra xong trước một hành động khác","past":"WHEN + S + V(quá khứ đơn) , S + V(quá khứ hoàn thành)","past_eg":"When I arrived at the airport, the plane had taken off.","future":"WHEN + S + V(hiện tại đơn) , S + V(tương lai hoàn thành)","future_eg":"When you return to the town, they will have finished building a new bridge."}]},"signals_text":"WHEN"},
{"id":"su-phoi-thi/theory/1","topic_id":"su-phoi-thi","position":1,"title":"Phối thì với AS SOON AS","usage_text":"ngay khi hành động này xảy ra thì hành động khác cũng xảy ra.","formula":{"custom":true,"rules":[{"title":"Diễn tả hành động xảy ra nối tiếp nhau","past":"AS SOON AS + S + V(quá khứ đơn) , S + V(quá khứ đơn)","past_eg":"As soon as she saw a mouse, she shouted and ran away.","future":"AS SOON AS + S + V(hiện tại đơn / hiện tại hoàn thành) , S + V(tương lai đơn)","future_eg":"I will call you as soon as I have finished / finish the work."}]},"signals_text":"AS SOON AS"},
{"id":"su-phoi-thi/theory/2","topic_id":"su-phoi-thi","position":2,"title":"Phối thì với SINCE","usage_text":"diễn tả hành động kéo dài từ một mốc thời gian trong quá khứ cho đến hiện tại.","formula":{"custom":true,"rules":[{"title":"Diễn tả nghĩa \"từ khi\"","formula":"S + V(hiện tại hoàn thành) + SINCE + V(quá khứ đơn)","eg":"We have known each other since we were at high school."}]},"signals_text":"SINCE"},
{"id":"su-phoi-thi/theory/3","topic_id":"su-phoi-thi","position":3,"title":"Phối thì với BY + TIME","usage_text":"diễn tả hành động kết thúc tính đến một điểm nào đó trong quá khứ hoặc tương lai.","formula":{"custom":true,"rules":[{"title":"Tính đến một điểm trong quá khứ","formula":"BY + trạng từ quá khứ + S + V(quá khứ hoàn thành)","eg":"By last month, we had worked for the company for 9 years."},{"title":"Tính đến một điểm trong tương lai","formula":"BY + trạng từ tương lai + S + V(tương lai hoàn thành)","eg":"By next month, we will have worked for the company for 9 years."}]},"signals_text":"BY"},
{"id":"su-phoi-thi/theory/4","topic_id":"su-phoi-thi","position":4,"title":"Phối thì với AT THIS/THAT TIME","usage_text":"diễn tả hành động đang xảy ra tại một thời điểm xác định trong quá khứ hoặc tương lai.","formula":{"custom":true,"rules":[{"title":"Thời điểm xác định trong quá khứ","formula":"AT THIS/THAT TIME + trạng từ quá khứ + S + V(quá khứ tiếp diễn)","eg":"At this time last week, we were preparing for Tet."},{"title":"Thời điểm xác định trong tương lai","formula":"AT THIS/THAT TIME + trạng từ tương lai + S + V(tương lai tiếp diễn)","eg":"At this time next week, we will be having a big party in the garden."}]},"signals_text":"AT THIS TIME\nAT THAT TIME"},
{"id":"su-phoi-thi/theory/5","topic_id":"su-phoi-thi","position":5,"title":"Phối thì với BY THE TIME","usage_text":"cho tới lúc, cho tới khi một hành động khác xảy ra.","formula":{"custom":true,"rules":[{"title":"Trong quá khứ","formula":"BY THE TIME + S + V(quá khứ đơn) , S + V(quá khứ hoàn thành)","eg":"By the time she got home, everyone had gone to bed."},{"title":"Trong tương lai","formula":"BY THE TIME + S + V(hiện tại đơn) , S + V(tương lai hoàn thành)","eg":"By the time she gets home, everyone will have gone to bed."}]},"signals_text":"BY THE TIME"},
{"id":"su-phoi-thi/theory/6","topic_id":"su-phoi-thi","position":6,"title":"Phối thì với AFTER","usage_text":"diễn tả hành động xảy ra xong rồi mới tới hành động khác.","formula":{"custom":true,"rules":[{"title":"Trong quá khứ (hành động xảy ra trước chia quá khứ hoàn thành)","formula":"AFTER + S + V(quá khứ hoàn thành) , S + V(quá khứ đơn)","eg":"After she had done her homework, she went out for a walk."},{"title":"Trong tương lai","formula":"AFTER + S + V(hiện tại hoàn thành) , S + V(hiện tại đơn)","eg":"After she has done her homework, she goes out for a walk."}]},"signals_text":"AFTER"},
{"id":"su-phoi-thi/theory/7","topic_id":"su-phoi-thi","position":7,"title":"Phối thì với BEFORE","usage_text":"diễn tả hành động xảy ra xong trước khi có hành động khác tới.","formula":{"custom":true,"rules":[{"title":"Trong quá khứ","formula":"BEFORE + S + V(quá khứ đơn) , S + V(quá khứ hoàn thành)","eg":"Before she went to bed, she had locked all the doors."},{"title":"Trong tương lai","formula":"BEFORE + S + V(hiện tại đơn) , S + V(tương lai hoàn thành)","eg":"Hurry up or the film will have ended before we go to the movie."}]},"signals_text":"BEFORE"},
{"id":"su-phoi-thi/theory/8","topic_id":"su-phoi-thi","position":8,"title":"Phối thì với UNTIL/TILL","usage_text":"diễn tả nghĩa \"cho tới khi\".","formula":{"custom":true,"rules":[{"title":"Công thức phối thì","formula":"S + V(tương lai đơn) / V(bare) / DON'T + V(bare) + UNTIL/TILL + S + V(hiện tại đơn / hiện tại hoàn thành)","eg":"I will wait for you until it is possible.\nWait here until I come back."}]},"signals_text":"UNTIL\nTILL"}
]
$seed$::jsonb)
  as x(id text, topic_id text, position integer, title text, usage_text text, formula jsonb, signals_text text);

