insert into public.exercise_questions (id, exercise_id, position, question_number, question_type, question_text, answer, explanation, options)
select x.* from jsonb_to_recordset($seed$
[
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":0,"question_number":1,"question_type":"fill","question_text":"The earth_goes__?__(go) around the sun.","answer":"goes","explanation":"Dịch: Trái đất quay quanh mặt trời. => Đây là sự thật hiển nhiên luôn đúng => chia thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":1,"question_number":2,"question_type":"choice","question_text":"Angela usually_____(leave) for work at 8:00","answer":"leaves","explanation":"Căn cứ vào trạng từ “usually” thì động từ trong câu phải chia thì hiện tại đơn.","options":{"A":"M."}},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":2,"question_number":3,"question_type":"fill","question_text":"Liz_____(get up) at 6 o’clock every morning.","answer":"gets up","explanation":"Căn cứ vào: \"every morning\" là dấu hiệu nhận biết thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":3,"question_number":4,"question_type":"fill","question_text":"In the summer, John often_____(play) tennis once or twice a week.","answer":"plays","explanation":"Căn cứ vào trạng từ “often” thì động từ trong câu phải chia thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":4,"question_number":5,"question_type":"fill","question_text":"What time you usually_____(get) home after work?","answer":"do you usually get","explanation":"Căn cứ vào trạng từ “usually” thì động từ trong câu phải chia thì hiện tại đơn. Đây là câu hỏi nên đảo trợ động từ lên trước chủ ngữ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":5,"question_number":6,"question_type":"fill","question_text":"The swimming pool_____(open) at 9:00 and_____(close) at 6:30 every day.","answer":"opens / closes","explanation":"Căn cứ vào cách dùng của thì hiện tại đơn: “nói về lịch trình hoặc thời gian biểu” thì động từ trong câu phải chia thì hiện tại đơn. => Hai động từ cùng có chung chủ ngữ là “the swimming pool” - danh từ số ít nên động từ cần chia số ít. – Dịch: Hàng ngày, bể bơi mở cửa lúc 9 giờ sáng và đóng cửa lúc 6 giờ 30 chiều.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":6,"question_number":7,"question_type":"fill","question_text":"Every year I_____(visit) Britain to improve my English.","answer":"visit","explanation":"Căn cứ vào từ \"every year\" là dấu hiệu nhận biết thì hiện tại đơn. Chủ ngữ “I”- danh từ ngôi thứ nhất => động từ chia số nhiều","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":7,"question_number":8,"question_type":"fill","question_text":"In the United State, elementary education is compulsory. All children _____ (study) six years of elementary school.","answer":"study","explanation":"Căn cứ vào cách dùng của thì hiện tại đơn: diễn tả những điều luôn đúng thì động từ trong câu phải chia thì hiện tại đơn. – Dịch: Ở Mỹ, giáo dục cơ bản là bắt buộc. Tất cả trẻ em phải học sáu năm học ở trường học sơ cấp.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":8,"question_number":9,"question_type":"fill","question_text":"I_____(not like) feel going to the library to study this afternoon.","answer":"don’t feel like","explanation":"Căn cứ vào cách dùng của thì hiện tại đơn: diển tả quan điểm, cảm giác hay suy nghĩ của người nói.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":9,"question_number":10,"question_type":"fill","question_text":"American people usually_____(have) their biggest meal in the evening.","answer":"have","explanation":"Căn cứ vào trạng từ “usually” thì động từ trong câu phải chia thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":10,"question_number":11,"question_type":"fill","question_text":"- Can you tell me when the train for HCM city_____(leave)? - In fifteen minutes. At 7.05.","answer":"leaves","explanation":"Căn cứ vào cách dùng của thì hiện tại đơn: “nói về lịch trình hoặc thời gian biểu” thì động từ trong câu phải chia thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":11,"question_number":12,"question_type":"fill","question_text":"Of course, you are Lisa, aren’t you? I_____(recognize) you now.","answer":"recognize","explanation":"Tạm dịch: Dĩ nhiên, bạn là Lisa phải không? Bây giờ tôi nhận ra bạn rồi. Căn cứ vào trạng từ \" now\" => chia thì hiện tại tiếp diễn. Tuy nhiên, động từ “recognize” không chia thì tiếp diễn nên ta chọn chia ở thì hiện tại đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":12,"question_number":13,"question_type":"fill","question_text":"I can see from what you say that your mornings are very busy! But what you (do)_____in the afternoons?","answer":"do you do","explanation":"Căn cứ vào ngữ cảnh của câu thì động từ trong câu phải chia thì hiện tại đơn. Chú ý: Đây là câu hỏi nên đảo trợ động từ lên trước chủ ngữ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":13,"question_number":14,"question_type":"fill","question_text":"Before our director_____(come back), I_____(want) to remind everyone that we should not use the internet on personal purposes.","answer":"comes back","explanation":"Căn cứ vào cách hợp thì với mệnh đề trạng ngữ chỉ thời gian: “Trong mệnh đề trạng ngữ chỉ thời gian ta dùng thì hiện tại đơn cho dù muốn diễn đạt hành động chưa xảy ra”. Trong ngữ cảnh trên, ông giám đốc chưa quay trở lại, nhưng vì mệnh đề này là mệnh đề trạng ngữ chỉ thời gian nên ta không dùng thì tương lai.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/0/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/0","position":14,"question_number":15,"question_type":"fill","question_text":"- Are you writing to him now? - Yes, I always_____(write) to him on his birthday. You_____ (want) to send any message? - Certainly.","answer":"write; Do","explanation":"Căn cứ vào trạng từ “always” thì động từ trong câu phải chia thì hiện tại đơn. Tuy nhiên trạng từ “always” có thể dùng với thì hiện tại tiếp diễn để nói về sự phàn nàn. Nhưng trong trường hợp này “always” đi với thì hiện tại đơn để diễn đạt sự “thường xuyên lặp đi lặp lại”. Chú ý: Vế hai là câu hỏi nên đảo trợ động từ lên trước chủ ngữ. Động từ “want” không chia thể tiếp diễn nên ta chia thì hiện tại đơn. - \"Bây giờ bạn đang viết thư cho anh ấy phải không?\" - \" Đúng vậy, tôi luôn luôn viết cho anh ấy vào ngày sinh nhật. Bạn muốn gửi lời nhắn nào không?\" - “Chắc chắn rồi.”","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":0,"question_number":1,"question_type":"fill","question_text":"It_____(rain) heavily now.","answer":"is raining","explanation":"* Căn cứ vào trạng từ “now” là dấu hiệu nhận biết thì hiện tại tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":1,"question_number":2,"question_type":"fill","question_text":"My brother_____(get) married next week.","answer":"is getting","explanation":"* Căn cứ vào cách dùng của thì hiện tại tiếp diễn: diễn tả hành động sẽ xảy ra trong tương lai (có kế hoạch từ trước). * Dịch nghĩa: Anh trai của tôi sẽ kết hôn vào tuần tới. - Vì việc kết hôn có kế hoạch từ trước => chia thì hiện tại tiếp diễn mang ý chỉ tương lai.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":2,"question_number":3,"question_type":"fill","question_text":"He is late again. He always_____(come) to class late.","answer":"is always coming","explanation":"* Căn cứ vào cách dùng của thì hiện tiếp diễn với trạng từ “always” nói về sự phàn nàn, ca thán về một thói quen trong hiện tại, ta dùng “be always Ving” * Dịch nghĩa: Anh ấy lại đến muộn. Anh ấy luôn luôn đến lớp muộn. => Vì vế trước có chứa “again”, nó đã thể hiện sự khó chịu của người nói, nên vế sau chỉ có thể diễn đạt theo dạng tiếp diễn mới có thể biểu đạt được ý phàn nàn này. Không thể dùng hiện tại đơn như một thói quen thông thường được.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":3,"question_number":4,"question_type":"fill","question_text":"She_____(take) the exam tomorrow.","answer":"is taking","explanation":"Căn cứ vào cách dùng của thì hiện tiếp diễn: nói về một kế hoạch cho tương lai đã có sự sắp xếp. Dịch: Cô ấy sẽ thi vào ngày mai.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":4,"question_number":5,"question_type":"fill","question_text":"Look! It_____(get) dark. Hurry up! It_____(rain) in a few minutes.","answer":"is raining","explanation":"Căn cứ vào động từ: Look! (nhìn kìa), Hurry up! (nhanh lên) - là dấu hiệu của thì hiện tại tiếp diễn. Lưu ý: Động từ “get” kết thúc bằng một phụ âm, đi trước là một nguyên âm nên ta gấp đôi phụ âm trước khi thêm -ing.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":5,"question_number":6,"question_type":"fill","question_text":"Please don’t make so much noise. I_____(work).","answer":"am working","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về hành động xảy ra ngay tại thời điểm nói.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":6,"question_number":7,"question_type":"fill","question_text":"I_____(read) an interesting book at the moment. I will lend it to you when I’ve finished it.","answer":"am reading","explanation":"Căn cứ vào “at the moment” là dấu hiệu của thì hiện tại tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":7,"question_number":8,"question_type":"fill","question_text":"Sarah_____(work) this week? - No, she is on vacation.","answer":"Is Sarah working","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về một sự việc xảy ra trong một khoảng thời gian gần với lúc nói, ví dụ như: today, this week. Chú ý: Đây là câu hỏi nên đảo trợ động từ lên trước chủ ngữ. - Tuần này Sarah có làm việc không? - Không, cô ấy đang có kỳ nghỉ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":8,"question_number":9,"question_type":"fill","question_text":"The population of the world_____(rise) very fast.","answer":"is rising","explanation":"* Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về những sự thay đổi đang diễn ra trong thời điểm nói. * Dịch: Dân số của thế giới đang tăng rất nhanh.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":9,"question_number":10,"question_type":"fill","question_text":"I_____(work) on the project of reconstructing city at present.","answer":"am working","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về sự việc xảy ra tại một thời điểm tương đối trong hiện tại (không nhất thiết đang xảy ra tại thời điểm nói).","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":10,"question_number":11,"question_type":"fill","question_text":"She is on vacation in France. She_____(have) a great time and doesn’t want to come back.","answer":"is having","explanation":"* Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về hành động xảy ra ngay tại thời điểm nói. * Dịch: Cô ấy đang đi nghỉ ở Pháp. Cô ấy đang có thời gian tuyệt vời và không muốn về.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":11,"question_number":12,"question_type":"fill","question_text":"Tom_____(look) for Ann. Do you know where she is?","answer":"is looking","explanation":"* Dịch nghĩa: Tom đang tìm Ann. Bạn biết cô ấy ở đâu không? => Hành động xảy ra ngay tại thời điểm nói. Thực tế Tom đang tìm Ann => chia thì hiện tại tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":12,"question_number":13,"question_type":"fill","question_text":"I_____(think) of my mother, who has devoted her whole life to our family.","answer":"am thinking","explanation":"Căn cứ vào động từ “think” – khi mô tả hành động thì “think” được coi là một động từ động, vẫn có thể đi với thể tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":13,"question_number":14,"question_type":"fill","question_text":"It is time we turned on the central heating. It_____(get) colder every day.","answer":"is getting","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về những sự thay đổi đang diễn ra trong thời điểm nói. - Vì “every day” cho thấy sự biến đổi đang diễn ra từng ngày theo thời gian chứ không phải là một dự định hay hiện tượng sẽ xảy ra trong tương lai gần nên không thể dùng “be going to Vo”; và đồng thời dù “every day” là dấu hiệu phổ biến trong thì hiện tại đơn nhưng trong ngữ cảnh này nó không được dùng như thế vì đó không phải là hành động lặp đi lặp lại như một thói quen","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/1/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/1","position":14,"question_number":15,"question_type":"fill","question_text":"-I_____(go) out to get an evening paper. - But it_____(rain). - Why don’t you wait till the rain stops?","answer":"is raining","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: nói về hành động xảy ra ngay tại thời điểm nói.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":0,"question_number":1,"question_type":"fill","question_text":"She_____(learn) English for three years.","answer":"has learnt","explanation":"Dịch: Cô ấy đã học tiếng Anh trong vòng 3 năm. Lưu ý: Câu này cũng có thể chia thì hiện tại hoàn thành tiếp diễn khi nhấn mạnh tính liên tục của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":1,"question_number":2,"question_type":"fill","question_text":"I’m hungry. I_____(not eat) anything since breakfast.","answer":"haven’t eaten","explanation":"","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":2,"question_number":3,"question_type":"fill","question_text":"He never_____(drive) a car before.","answer":"has never driven","explanation":"Dịch: Anh ấy chưa bao giờ lái xe trước đây.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":3,"question_number":4,"question_type":"fill","question_text":"We_____(know) each other since we were at high school.","answer":"have known","explanation":"Dịch: Chúng tôi đã biết nhau từ khi chúng tôi ở trường cấp ba.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":4,"question_number":5,"question_type":"fill","question_text":"Everything is going well. We_____(not have) any problem so far.","answer":"haven’t had","explanation":"Dịch: Mọi thứ đang trở nên tốt hơn. Cho đến nay chúng tôi chưa có bất cứ vấn đề nào.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":5,"question_number":6,"question_type":"fill","question_text":"I_____(drink) four cups of coffee today.","answer":"have drunk","explanation":"Dịch: Tôi đã uống 4 cốc cà phê hôm nay.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":6,"question_number":7,"question_type":"fill","question_text":"John_____(live) in Denver since 2017.","answer":"has lived","explanation":"Dịch: John đã sống ở Denver từ năm 2017.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":7,"question_number":8,"question_type":"fill","question_text":"- You ever_____(climb) Mount Everest? - No, I haven’t. But I’m sure I will, if I have a chance.","answer":"have you ever climbed","explanation":"Dịch: - Bạn đã leo núi Everest chưa? - Không, tôi chưa. Nhưng tôi chắc chắn tôi sẽ làm, nếu tôi có cơ hội.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":8,"question_number":9,"question_type":"fill","question_text":"It is nice to see you again. We_____(not see) each other for a long time.","answer":"haven’t seen / haven’t been seeing","explanation":"Dịch: Thật tốt để gặp lại bạn một lần nữa. Chúng ta chưa gặp nhau trong một thời gian dài.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":9,"question_number":10,"question_type":"fill","question_text":"I_____(forget) my key. I can’t unlock the door now.","answer":"have forgotten","explanation":"Dịch: Tôi đã lám mất chìa khóa của mình. Bây giờ tôi không thể mở cửa.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":10,"question_number":11,"question_type":"fill","question_text":"Eric is calling his girlfriend again. That is the third time he_____(call) her this evening.","answer":"has called","explanation":"Dịch: Eric lại đang gọi cho bạn gái của anh ấy. Đây là lần thứ ba anh ấy gọi cho cô ấy trong tối nay.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":11,"question_number":12,"question_type":"fill","question_text":"The police_____(arrest) two men in connection with the robbery.","answer":"have arrested","explanation":"Dịch: Cảnh sát đã bắt 2 người liên quan đến vụ cướp.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":12,"question_number":13,"question_type":"fill","question_text":"Susan really loves that film. She_____(see) it eight times!","answer":"has seen","explanation":"Dịch: Susan thực sự thích bộ phim đó. Cô ấy đã xem nó 8 lần!","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":13,"question_number":14,"question_type":"fill","question_text":"You already_____(read) the book? What do you think?","answer":"have you already read","explanation":"Dịch: Bạn đã đọc cuốn sách rồi phải không? Bạn nghĩ gì?","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/2/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/2","position":14,"question_number":15,"question_type":"fill","question_text":"I_____(not go) to a zoo before. It is a nice feeling to go somewhere you never_____(be) before.","answer":"haven’t gone; have never been","explanation":"Dịch: Tôi chưa từng đi đến vườn bách thú trước đây. Đó là cảm giác tuyệt vời để đi đến nơi nào đó bạn chưa từng đến từ trước.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":0,"question_number":1,"question_type":"fill","question_text":"He_____(wait) all the morning.","answer":"has been waiting","explanation":"* Dịch nghĩa: Anh ấy đã chờ cả buổi sáng. * Căn cứ: - “all the morning”: nhấn mạnh tính liên tục của hành động “chờ”. => chia thì hiện tại hoàn thành tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":1,"question_number":2,"question_type":"fill","question_text":"Richard_____(do) the same job for 20 years.","answer":"has been doing","explanation":"* Dịch nghĩa: Richard đã làm công việc giống nhau trong vòng 20 năm. * Căn cứ: - “for 20 years” nhấn mạnh tính liên tục đã “làm trong vòng 20 năm”. => chia thì hiện tại hoàn thành tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":2,"question_number":3,"question_type":"fill","question_text":"I_____(study) English for six months.","answer":"have been studying","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh tính liên tục của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":3,"question_number":4,"question_type":"fill","question_text":"Mike_____(work) in Las Vegas for the last few months.","answer":"has been working","explanation":"* Dịch nghĩa: Mike đã làm việc ở Vegas trong một vài tháng cuối. * Căn cứ vào: + “for the last few months” nhấn mạnh đến khoảng thời gian “trong một vài tháng cuối”.=> nhấn mạnh tính liên tục của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":4,"question_number":5,"question_type":"fill","question_text":"It_____(rain) since lunchtime.","answer":"has been raining / has rained","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh quá trình hành động đã, đang và sẽ có thể xảy ra liên tục trong một khoảng thời gian nhất định. Có thể dùng cả thì hiện tại hoàn thành, diễn tả hành động kéo dài từ quá khứ đến hiện tại và có thể tiếp tục trong tương lai, mặc dù nó chủ yếu nhấn mạnh đến kết quả để lại. Nhưng với dạng bài tập tự luận thì cả hai đều chấp nhận được.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":5,"question_number":6,"question_type":"fill","question_text":"Helen_____(read) this book for three days.","answer":"has been reading","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: chỉ hành động lặp đi lặp lại trong một khoảng thời gian.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":6,"question_number":7,"question_type":"fill","question_text":"Kevin_____(look) for a job since he finished school.","answer":"has been looking","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh hành động đang xảy ra. Để nhấn mạnh quá trình xảy ra của hành động, ta dùng thì hiện tại hoàn thành tiếp diễn sẽ chính xác hơn là thì hiện tại hoàn thành - nhấn mạnh kết quả","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":7,"question_number":8,"question_type":"fill","question_text":"I’m tired of waiting. I_____(sit) here for one hour.","answer":"have been sitting","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh tính liên tục của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":8,"question_number":9,"question_type":"fill","question_text":"He is exhausted because he_____(work) continuously for more than twelve hours.","answer":"has been working","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: chỉ hành động lặp đi lặp lại trong một khoảng thời gian.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":9,"question_number":10,"question_type":"fill","question_text":"She_____(sleep) for 10 hours! You must wake her.","answer":"has been sleeping","explanation":"Dịch nghĩa: Cô ấy đã ngủ suốt 10 tiếng đồng hồ rồi! Bạn phải đánh thức cô ấy thôi. + “ngủ” là hành động xảy ra trong quá khứ. Vế 2 “Bạn phải đánh thức cô ấy” => có nghĩa cô ấy vẫn chưa dậy. => kéo dài đến hiện tại. + “for 10 hours” => nhấn mạnh tính liên tục của việc “ngủ” của cô ấy kéo dài “trong mười giờ”.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":10,"question_number":11,"question_type":"fill","question_text":"He_____(read) this book for two hours, but he hasn’t finished it yet.","answer":"has been reading","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh tính liên tục của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":11,"question_number":12,"question_type":"fill","question_text":"That boy_____(wait) for the bus for half an hour. Shall I tell him that the last bus has already gone?","answer":"has been waiting","explanation":"* Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: nhấn mạnh tính liên tục của hành động. - \" for half an hour \" nhấn mạnh “thời gian liên tục cậu bé chờ”.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":12,"question_number":13,"question_type":"fill","question_text":"They_____(argue) very excitedly all this time. Shall I come and interrupt them?","answer":"have been arguing","explanation":"* Dịch nghĩa: Họ đã tranh luận một cách hào hứng mọi lúc. Liệu tôi có thể đến và ngắt lời họ không? * Căn cứ vào: + “all the time” (mọi lúc) nhấn mạnh tính liên tục của hành động. + họ tranh luận mọi lúc. => chia hiện tại hoàn thành tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":13,"question_number":14,"question_type":"fill","question_text":"What have you done with my bag? I_____(look) for it for an hour and I haven’t found it yet.","answer":"have been looking","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: khi nói về những hành động đã kết thúc gần đây hay mới kết thúc nhưng kết quả còn ảnh hưởng đến hiện tại.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/3/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/3","position":14,"question_number":15,"question_type":"fill","question_text":"I_____(think) over what you said since yesterday.","answer":"have been thinking","explanation":"Dịch nghĩa: Tôi đã nghĩ về những điều bạn nói từ ngày hôm qua. + \"đã nghĩ\" là hành động bắt đầu trong quá khứ, kéo dài đến hiện tại và chưa nhắc đến thời điểm kết thúc. => nhấn mạnh tính liên tục của hành động (since yesterday: từ ngày hôm qua).","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":0,"question_number":1,"question_type":"choice","question_text":"We can go out now. It_____anymore.","answer":"A","explanation":"Căn cứ: cách dùng của thì hiện tại tiếp diễn: Diễn đạt 1 hành động sắp xảy ra trong tương lai gần (thường là chắc chắn)\u000bDịch nghĩa: Chúng ta có thể ra ngoài bây giờ. Trời sẽ không còn mưa nữa.","options":{"A":"isn’t raining","B":"rains","C":"has rained","D":"has been raining"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":1,"question_number":2,"question_type":"choice","question_text":"What_____in your spare time? Do you have any hobbies?","answer":"C","explanation":"Căn cứ: cách sử dụng của thì hiện tại đơn: diễn tả một thói quen hay hành động diễn ra thường xuyên, lặp đi lặp lại ở hiện tại. (làm gì trong thời gian rảnh rỗi).\u000b- Dịch nghĩa: Bạn thường làm gì trong thời gian rảnh? Bạn có sở thích gì không?","options":{"A":"have you done","B":"are you doing","C":"do you do","D":"have you been doing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":2,"question_number":3,"question_type":"choice","question_text":"Mary usually_____me on Fridays, but she didn’t call last Friday.","answer":"B","explanation":"Căn cứ: “usually” là dấu hiệu nhận biết thì hiện tại đơn. \nDịch nghĩa: Mary thường gọi cho tôi vào những ngày thứ sáu, nhưng thứ 6 tuần trước lại không thấy cô ấy gọi cho tôi.","options":{"A":"have been calling","B":"calls","C":"is calling","D":"have called"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":3,"question_number":4,"question_type":"choice","question_text":"I_____hungry. Let’s have something to eat.","answer":"A","explanation":"Căn cứ vào cách dùng của “feel”: có thể dùng thì “present simple tense” hay “present continuous tense” khi diễn tả cảm giác của người nào đó vào thời điểm nói. \n*Vế sau dùng “let’s” để chỉ hành động rủ nhau cùng đi làm gì ở thời điểm nói, nên có thể hình dung hành động “đang thấy đói” nó cũng đang xảy ra ngay lúc đó luôn, nên chia hiện tại tiếp diễn là phù hợp nhất. Dù có thể suy luận thành thì hiện tại hoàn thành (tiếp diễn), diễn tả hành động kéo dài liên tục từ trong quá khứ đến hiện tại, nhưng vẫn không chính xác vì nó không có dấu hiệu của việc kéo dài này nên không nên suy luận như vậy.\u000b- Dịch nghĩa: Tôi đang cảm thấy đói. Hãy đi ăn gì đi.","options":{"A":"am feeling","B":"have felt","C":"feel","D":"have been feeling"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":4,"question_number":5,"question_type":"choice","question_text":"What is that noise? What_____?","answer":"B","explanation":"Căn cứ vào cách dùng của thì hiện tại tiếp diễn: diễn tả những hành động xảy ra ngay tại thời điểm nói.\u000b- Dịch nghĩa: Tiếng ồn đó là gì? Điều gì đang xảy ra vậy?","options":{"A":"have been happening","B":"is happening","C":"have happened","D":"had happened"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":5,"question_number":6,"question_type":"choice","question_text":"It’s usually dry here at this time of the year. It_____much.","answer":"D","explanation":"Căn cứ cách dùng của thì hiện tại đơn: diễn tả những sự việc xảy ra thường xuyên.\u000b- Dịch nghĩa: Ở đây trời thường khô vào thời điểm này trong năm. Trời không mưa nhiều.\u000b+ Việc “không mưa” thường xuyên xảy ra => chia thì hiện tại đơn","options":{"A":"isn’t raining","B":"hasn’t rained","C":"hasn’t been raining","D":"doesn’t rain"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":6,"question_number":7,"question_type":"choice","question_text":"Look! That man over there_____the same sweater as you.","answer":"B","explanation":"* Căn cứ: “Look!” là dấu hiệu nhận biết thì hiện tại tiếp diễn.\n* Chủ ngữ là “That man” => “To be” chia là “is”.\n => Đáp án: is wearing\u000b* Dịch nghĩa: Nhìn kìa! Người đàn ông đó đang mặc áo len dài giống bạn.","options":{"A":"has worn","B":"is wearing","C":"wears","D":"have been wearing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":7,"question_number":8,"question_type":"choice","question_text":"I wonder why Jim_____so nice to me today. He isn’t usually like that.","answer":"A","explanation":"* Dịch: Tôi không hiểu tại sao hôm nay anh ấy lại tốt với tôi thế. Bình thường anh ta đâu có như thế. \n* Căn cứ vào:\u000b+ Thì hiện tại đơn: diễn tả thói quen ở hiện tại.\n+ Thì hiện tại tiếp diễn: diễn tả sự thay đổi của thói quen.","options":{"A":"is being","B":"have been","C":"is","D":"have being"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":8,"question_number":9,"question_type":"choice","question_text":"Mary wasn’t happy with her new job at first, but she_____to like it now.","answer":"C","explanation":"Dịch: Đầu tiên Mary không vui vẻ với công việc mới của cô ấy, nhưng bây giờ cô ấy đang dần bắt đầu thích nó.\n=> Căn cứ vào cách dùng của thì hiện tại tiếp diễn “diễn tả sự thay đổi của trạng thái, điều kiện, thói quen”. Trong câu trên “cô ấy bắt đầu thích” => chia thì hiện tại tiếp diễn.","options":{"A":"begins","B":"have begun","C":"is beginning","D":"have been beginning"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":9,"question_number":10,"question_type":"choice","question_text":"This is a nice restaurant, isn’t it? Is this the first time you_____here?","answer":"B","explanation":"Căn cứ vào cấu trúc: This is the first / second / third … time + S + V (hiện tại hoàn thành).\u000b( Đây là lần đầu tiên/thứ hai/thứ ba… ai đó làm gì)\u000b- Dịch nghĩa: Đây là một nhà hàng ngon phải không? Đây có phải là lần đầu tiên bạn đến đây không?","options":{"A":"are","B":"have been","C":"are being","D":"have being"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":10,"question_number":11,"question_type":"choice","question_text":"I need a new job. I_____the same job for too long.","answer":"C","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành tiếp diễn: diễn tả hành động bắt đầu ở quá khứ và tiếp diễn tới hiện tại (nhấn mạnh tính liên tục).\u000b- Dịch nghĩa: Tôi cần một công việc mới. Tôi đã làm cùng một công việc quá lâu.\u000b+ “đã làm cùng một công việc” là hành động lặp đi lặp lại, kéo dài đến hiện tại. => Chia thì hiện tại hoàn thành tiếp diễn.","options":{"A":"are doing","B":"have done","C":"have been doing","D":"do"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":11,"question_number":12,"question_type":"choice","question_text":"“You look tired”. “Yes, I_____basketball”.","answer":"D","explanation":"Dịch nghĩa: “Em trông có vẻ mệt mỏi” - \" Vâng nãy giờ em đã chơi bóng rổ.\"\n=> Với vế đầu gợi ý về sự mệt mỏi thì vế sau cần phải nhấn mạnh vào quá trình chơi bóng rổ lâu dài trước đó (vì chơi liên tục trong thời gian dài trước đó nên mới mệt), do đó ta dùng thì hiện tại hoàn thành tiếp diễn là phù hợp nhất.","options":{"A":"plays","B":"is playing","C":"have played","D":"have been playing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":12,"question_number":13,"question_type":"choice","question_text":"I would like to see Tina again. It’s been a long time_____.","answer":"C","explanation":"Căn cứ vào cấu trúc: It is + thời gian + since + V (quá khứ đơn).\u000b- Dịch nghĩa: Tôi muốn gặp Tina một lần nữa. Đã từ nhiều năm kể từ lần cuối tôi gặp cô ấy.\u000b+ Loại A, B: vì sai cấu trúc.\u000b+ Loai D: không hợp nghĩa. (cho đến khi tôi gặp cô ấy).\u000b=> Chọn C.","options":{"A":"that I didn’t see her","B":"for I didn’t see her","C":"since I saw her","D":"until I saw her"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":13,"question_number":14,"question_type":"choice","question_text":"Bod and Alice have been married_____.","answer":"D","explanation":"Căn cứ:\u000b+ for + khoảng thời gian. Ex: I have learnt English for six years.\u000b+ since + mốc thời gian. Ex: I have learnt English since 2013.\u000b- Dịch nghĩa: Bob và Alice đã kết hôn được 20 năm.","options":{"A":"that 20 years","B":"since 20 years","C":"when 20 years","D":"for 20 years"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":14,"question_number":15,"question_type":"choice","question_text":"- I am looking for Paul. You_____him? - Yes, he was here a minute ago.","answer":"A","explanation":"Căn cứ vào cách dùng của thì hiện tại hoàn thành: diễn tả hành động xảy ra trong quá khứ nhưng không rõ thời gian\u000b- Dịch nghĩa: Tôi đang tìm Paul. Bạn có thấy anh ấy không? - Có, anh ấy đã ở đây một phút trước.","options":{"A":"Have - seen","B":"Did - see","C":"Do - see","D":"Is - seeing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/16","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":15,"question_number":16,"question_type":"choice","question_text":"Unless she_____extra, she will not complete the work.","answer":"D","explanation":"Căn cách dùng của “unless” trong câu điều kiện loại 1: \n      Unless + S + V (hiện tại đơn), S + will/ can/ may + V (bare)\u000b- Dịch nghĩa: Nếu cô ấy không được trả thêm, cô ấy sẽ không hoàn thành công việc.\u000b=> Vế cần chia mang nghĩa bị động.","options":{"A":"is paying","B":"have been paying","C":"pays","D":"is paid"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/17","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":16,"question_number":17,"question_type":"choice","question_text":"The house at the end of the street which_____empty for years has been sold.","answer":"D","explanation":"Căn cứ dấu hiệu của thì hiện tại hoàn thành: for + khoảng thời gian.\u000b- Dịch nghĩa: Căn nhà ở cuối đường mà bị bỏ trống trong nhiều năm đã được bán.","options":{"A":"is","B":"have been","C":"is being","D":"has been"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/18","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":17,"question_number":18,"question_type":"choice","question_text":"All right, you’ll try to fix the television! But I_____you know what you’re doing.","answer":"A","explanation":"=> Key: A. hope\u000b=> Vì: không có dấu hiệu về thì rõ ràng và dịch theo nghĩa nên để hiện tại đơn\u000b=> Dịch: Được rồi, bạn sẽ cố gắng sửa tivi! Nhưng tôi hi vọng bạn biết bạn đang làm gì.","options":{"A":"hope","B":"have hoped","C":"is hoping","D":"have been hoping"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/19","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":18,"question_number":19,"question_type":"choice","question_text":"Who_____at the door?","answer":"B","explanation":"=> Key: B. is knocking\u000b=> Vì: theo cách dùng của thì hiện tại tiếp diễn, diễn tả một sự việc bất thường, đang diễn ra tại thời điểm nói\u000b=> Dịch: Ai đang gõ cửa vậy?","options":{"A":"knock","B":"is knocking","C":"have been knocking","D":"have knocked"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/20","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":19,"question_number":20,"question_type":"choice","question_text":"How long it_____you to get to the library?","answer":"A","explanation":"Căn cứ vào ngữ cảnh của câu ta chia thì hiện tại đơn.\nCấu trúc: \nIt takes sb time to do st: mất của ai đó bao nhiêu thời gian để làm gì\u000b- Dịch nghĩa: Mất bao lâu để bạn đi đến thư viện?","options":{"A":"does - take","B":"have - taken","C":"is - taking","D":"have - been taking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/21","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":20,"question_number":21,"question_type":"choice","question_text":"Many girls want to go to the pub while only a minority_____to watch TV at home now.","answer":"D","explanation":"Dịch: Ngày nay trong khi nhiều cô gái muốn đến quán rượu thì chỉ có một nhóm ít người muốn ở nhà xem TV. \n=> “Minority” là một danh từ tập hợp, khi nó đi với “of” thì sẽ chia theo danh từ sau “of”. Nhưng trường hợp nó đứng một mình, thì nó thường đi với động từ số ít nhưng cũng có thể đi với động từ số nhiều tùy theo hàm ý của người nói. Có hai trường hợp phổ biến sau:\n- Khi danh từ tập hợp được đề cập đến như là các thành viên của một nhóm… thì động từ theo sau là số nhiều. \n- Khi danh từ tập hợp được đề cập đến như là một nhóm, một đơn vị riêng rẽ thì động từ theo sau là số ít.\n=> Xét ngữ cảnh trong câu, vì vế trước người ta cũng chỉ nói chung chung với hàm ý một nhóm nhiều cô gái, ý nói có nhiều người (nhưng khi dùng “many + N(số nhiều)” thì động từ luôn chia số nhiều) thì vế sau cũng hàm ý chỉ một nhóm người, một tập hợp nào đó được xem như một đơn vị riêng lẻ nhưng chỉ có rất ít người, để chỉ hai nhóm người có đặc điểm đối lập nhau chứ không có ý chỉ các cô gái cụ thể nào trong nhóm ấy.\n=> Theo cách dùng thứ hai, ta chia động từ số ít là “wants”.","options":{"A":"is wanting","B":"want","C":"will want","D":"wants"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/22","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":21,"question_number":22,"question_type":"choice","question_text":"They’ve faxed me I should stay till they_____a replacement. Well, last time it took two weeks.","answer":"C","explanation":"Dịch: Họ đã gửi fax cho tôi bảo tôi nên ở lại cho đến khi họ tìm được người thay thế. Ồ, lần trước phải mất đến hai tuần. \nXét hành động tìm người thay thế chưa xảy ra nên động từ sau “till” chia hiện tại đơn.","options":{"A":"found","B":"will find","C":"find","D":"had found"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/23","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":22,"question_number":23,"question_type":"choice","question_text":"Let’s have some tea. It_____chilly.","answer":"B","explanation":"=> Key: B. is getting\u000b=> Vì: theo cách dùng của thì hiện tại tiếp diễn, diễn tả một sự thay đổi, một việc đang diễn ra ở thời điểm nói\u000b=> Dịch: Chúng ta hãy uống trà nhé. Thời tiết đang trở lạnh rồi.","options":{"A":"gets","B":"is getting","C":"have gotten","D":"have been getting"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/24","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":23,"question_number":24,"question_type":"choice","question_text":"Don’t talk to him while he_____.","answer":"C","explanation":"=> Key: C. is reading\u000b=> Dựa vào ngữ cảnh của câu và dấu hiệu “while: trong khi” => hiện tại tiếp diễn\u000b=> Dịch: Đừng nói chuyện với anh ấy trong khi anh ấy đang đọc sách.","options":{"A":"have been reading","B":"reads","C":"is reading","D":"have read"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/25","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":24,"question_number":25,"question_type":"choice","question_text":"Ann wants to see you. You_____here for ages!","answer":"A","explanation":"Căn cứ: “for + khoảng thời gian” là dấu hiệu nhận biết thì hiện tại hoàn thành.\u000b- Dịch nghĩa: Ann muốn gặp bạn. Bạn đã ở đây nhiều năm rồi.","options":{"A":"have been","B":"are","C":"had been","D":"are being"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/26","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":25,"question_number":26,"question_type":"choice","question_text":"- Your house is very beautiful. How long you_____here? - Nearly ten years.","answer":"B","explanation":"=> Vì: dựa vào câu trả lời về khoảng thời gian và cách dùng của thì hiện tại hoàn thành tiếp diễn (diễn tả một hành động bắt đầu ở quá khứ, vẫn còn tiếp tục ở hiện tại và có thể kéo dài đến tương lai, nhấn mạnh vào thời gian, quá trình)\u000b=> Dịch: - Ngôi nhà của bạn rất đẹp. Bạn đã ở đây bao lâu rồi?\u000b- Gần mười năm.","options":{"A":"did - live","B":"have - been living","C":"do - live","D":"is - living"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/27","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":26,"question_number":27,"question_type":"choice","question_text":"I_____to the movies for ages. We used to go a lot.","answer":"A","explanation":"=> Vì: có dấu hiệu for ages => Dùng thì hiện tại hoàn thành để diễn tả một hành động đã kéo dài từ trong quá khứ đến hiện tại.\u000b=> Dịch: Tôi đã không tới rạp chiếu phim trong một thời gian dài. Chúng tới đã từng tới đó rất nhiều lần.","options":{"A":"haven’t gone","B":"didn’t go","C":"isn’t going","D":"hadn’t gone"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/28","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":27,"question_number":28,"question_type":"choice","question_text":"Why are you putting on your coat? You_____out?","answer":"D","explanation":"Dịch: Sao bạn lại mặc áo khoác vào thế? Bạn định ra ngoài à?\nGiải thích: \n- Căn cứ vào dấu hiệu ở hiện tại \"đang mặc áo khoác\", ta suy ra việc “ra ngoài” là có kế hoạch từ trước. \n-> Căn cứ vào cách dùng của thì hiện tại tiếp diễn, diễn tả một hành động chắc chắn sẽ xảy ra vì có kế hoạch từ trước.","options":{"A":"Do - go","B":"Have - gone","C":"Had - gone","D":"Are - going"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/29","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":28,"question_number":29,"question_type":"choice","question_text":"Look! That plane_____toward the airport. It is going to land.","answer":"C","explanation":"=> Key: C. is flying\u000b=> Vì: có từ Look! và theo cách dùng của hiện tại tiếp diễn: diễn tả một hành động đang diễn ra tại thời điểm nói\u000b=> Dịch: Nhìn này! Chiếc máy bay đó đang bay về hướng sân bay. Nó sắp hạ cánh","options":{"A":"flies","B":"have flown","C":"is flying","D":"will fly"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/30","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":29,"question_number":30,"question_type":"choice","question_text":"Ann is very tired. She_____tennis for three hours.","answer":"D","explanation":"=> Key: D. has been playing\u000b=> Vì: có for + khoảng thời gian và cách dùng hiện tại hoàn thành tiếp diễn nhấn mạnh vào thời gian, quá trình.\u000b=> Dịch: Ann rất mệt mỏi. She đã chơi tennis trong ba giờ","options":{"A":"is playing","B":"will play","C":"plays","D":"has been playing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/31","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":30,"question_number":31,"question_type":"choice","question_text":"He works in a bank, but he_____it very much.","answer":"A","explanation":"Căn cứ: cách sử dụng của thì hiện tại đơn: diễn tả thói quen, sở thích, quan điểm của người nói.\u000b- Dịch nghĩa: Anh ấy làm việc ở một ngân hàng, nhưng anh ấy không thích công việc này lắm.","options":{"A":"doesn’t enjoy","B":"haven’t enjoyed","C":"didn’t enjoy","D":"hadn’t enjoyed"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/32","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":31,"question_number":32,"question_type":"choice","question_text":"I_____well lately. Maybe I should go to the doctor.","answer":"C","explanation":"Căn cứ: \"lately\" là dấu hiệu nhận biết thì hiện tại hoàn thành. Câu này nhấn mạnh tính liên tục của hành động ta dùng thì hiện tại hoàn thành tiếp diễn. \u000b- Dịch nghĩa: Gần đây tôi không cảm thấy khỏe. Có lẽ tôi nên đi khám bác sĩ.","options":{"A":"didn’t feel","B":"won’t feel","C":"haven’t been feeling","D":"am not feeling"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/33","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":32,"question_number":33,"question_type":"choice","question_text":"I_____my homework for two hours, but I_____yet.","answer":"D","explanation":"=> Key: D. have been doing – haven’t finished\u000b=> Vì: do có dấu hiệu for two hours và yet nên chia thì hiện tại hoàn thành, mà câu đầu tiên nhấn mạnh vào thời gian, quá trình làm nên để hiện tại hoàn thành tiếp diễn, câu 2 nhân mạnh vào kết quả nên chỉ cần chia hiện tại hoàn thành\u000b=> Dịch: Tôi đã làm bài tập về nhà của tôi trong hai giờ, nhưng tôi vẫn chưa xong.","options":{"A":"have done - haven’t finished","B":"is doing - isn’t finishing","C":"will do - will not finish","D":"have been doing - haven’t finished"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/34","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":33,"question_number":34,"question_type":"choice","question_text":"Let’s take our travel chess set in case we_____bored on the train.","answer":"A","explanation":"=> Vì: sau in case luôn chia thì hiện tại đơn\u000b=> Dịch: Hãy đem theo bộ cờ du lịch của chúng ta trong trường hợp chúng ta thấy chán trên tàu","options":{"A":"get","B":"are getting","C":"got","D":"have got"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/35","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":34,"question_number":35,"question_type":"choice","question_text":"We_____get in touch with our customers by post.","answer":"B","explanation":"A. recently: gần đây\nB. hardly: hầu như không, ít khi\nC. lately: gần đây\nD. latterly: gần đây, mới đây\n=> Căn cứ vào động từ “get” chia ở thì hiện tại đơn nên ta loại đáp án A,C, D.\n- Dịch nghĩa: Chúng tôi ít khi liên lạc với khách hàng qua đường bưu điện.","options":{"A":"recently","B":"hardly","C":"lately","D":"latterly"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/36","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":35,"question_number":36,"question_type":"choice","question_text":"We have been married_____.","answer":"C","explanation":"Căn cứ: “for + khoàng thời gian”; “since + mốc thời gian”.\u000b- Dịch nghĩa: Chúng tôi đã kết hôn hơn hai mươi năm.","options":{"A":"over twenty years","B":"over twenty years ago","C":"for over twenty years","D":"since over twenty years"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/37","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":36,"question_number":37,"question_type":"choice","question_text":"Melanie_____her hand. It’s bleeding heavily.","answer":"A","explanation":"Dịch: Melanie đã bị đứt tay. Máu đang chảy rất nhiều. \n=> Hành động đứt tay đã xảy ra trong quá khứ nhưng để lại hậu quả ở hiện tại nên ta chia ở thì hiện tại hoàn thành.","options":{"A":"has cut","B":"is cutting","C":"cut","D":"cuts"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/38","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":37,"question_number":38,"question_type":"choice","question_text":"“When will Mary be able to leave hospital?” - “Don’t be so impatient. We cannot release her before we_____the last test.”","answer":"A","explanation":"Dịch nghĩa: \n- “Khi nào Mary có thể xuất viện?”\n- “Đừng nôn nóng thế. Chúng tôi không thể cho cô ấy xuất viện trước khi chúng tôi khám xong cho cô ấy lần cuối.”\n=> Mệnh đề trạng ngữ chỉ thời gian before không chia thì tương lai nên ta loại phương án B, C. \n=> Xét nghĩa của câu ta thấy việc khám cho Mary chưa diễn ra nên ta không thể chia thì quá khứ đơn. Do đó, loại phương án D.","options":{"A":"have completed","B":"will have completed","C":"will complete","D":"completed"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/39","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":38,"question_number":39,"question_type":"choice","question_text":"The Amazon River_____into the Atlantic Ocean.","answer":"A","explanation":"=> Key: A. flows\u000b=> Vì: cách dùng của hiện tại đơn: diễn tả một sự thật hiển nhiên\u000b=> Dịch: Sông Amazon chảy vào Đại Tây Dương","options":{"A":"flows","B":"has flowed","C":"is flowing","D":"will flow"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/40","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":39,"question_number":40,"question_type":"choice","question_text":"My parents live in_____London. They_____there_____all their lives.","answer":"C","explanation":"=> Key: C. have lived\u000b=> Vì: cách dùng của thì hiện tại hoàn thành: diễn tả một hành động bắt đầu ở quá khứ, vẫn còn tiếp tục ở hiện tại và có thể kéo dài đến tương lai\u000b=> Dịch: Bố mẹ tôi sống ở London. Họ đã sống cả cuộc đời ở đó.","options":{"A":"are living","B":"had lived","C":"have lived","D":"will live"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/41","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":40,"question_number":41,"question_type":"choice","question_text":"Where have you been? I_____for you for the last half hour.","answer":"B","explanation":"=> Key: B. have been looking\u000b=> Vì: : có for + khoảng thời gian => hiện tại hoàn thành. Khi muốn nhấn mạnh tính liên tục của hành động ta dùng thì hiện tại hoàn thành tiếp diễn; \u000b=> Dịch: Bạn đã ở đâu? Tôi đã tìm bạn trong nửa giờ qua.","options":{"A":"am looking","B":"have been looking","C":"will be looking","D":"look"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/42","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":41,"question_number":42,"question_type":"choice","question_text":"My brother is an actor. He_____in several movies.","answer":"C","explanation":"Dịch: Anh tôi là một diễn viên. Anh ấy đã xuất hiện trong một vài bộ phim. \nGiải thích: “đã xuất hiện trong một vài bộ phim” là hành động lặp đi lặp lại nhiều lần trong quá khứ nên ta chia thì hiện tại hoàn thành. \nĐáp án C","options":{"A":"appeared","B":"had appeared","C":"has appeared","D":"appears"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/43","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":42,"question_number":43,"question_type":"choice","question_text":"Please don’t bother him now. He_____.","answer":"A","explanation":"Dịch: Bây giờ đừng làm phiền anh ấy. Anh ấy đang làm việc.\n=> Vế trước đã cho thấy dấu hiệu hành động đang xảy ra tại thời điểm nói (now), do đó ta chia động từ ở thì hiện tại tiếp diễn.","options":{"A":"is working","B":"has been working","C":"had been working","D":"was working"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/44","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":43,"question_number":44,"question_type":"choice","question_text":"I_____an interesting book at the moment. I will lend it to you when I_____it.","answer":"A","explanation":"Căn cứ: “at the moment” là dấu hiệu nhận biết thì hiện tại tiếp diễn.\u000b- Dịch nghĩa: Tại thời điểm này, tôi đang đọc một cuốn sách thú vị. Tôi sẽ cho bạn mượn nó khi tôi đọc xong.","options":{"A":"am reading - have finished","B":"read - am finishing","C":"have read - am finishing","D":"read - will finish"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/45","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":44,"question_number":45,"question_type":"choice","question_text":"Ha never_____fishing in the winter but she always_____it in the summer.","answer":"A","explanation":"Căn cứ: trạng từ “never” và “always” là dấu hiệu nhận biết thì hiện tại đơn. Đồng thời, câu đang mô tả một thói quen lặp đi lặp lại của một ai đó nên ta dùng thì hiện tại đơn.\u000b- Dịch nghĩa: Hà không bao giờ đi câu cá vào mùa đông nhưng cô ấy luôn luôn làm vào mùa hè.","options":{"A":"goes - does","B":"has gone - done","C":"go - do","D":"was gone - done"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/46","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":45,"question_number":46,"question_type":"choice","question_text":"We can win only if we remain united, so we must support them the moment they_____on strike.","answer":"C","explanation":"Tạm dịch: Chúng ta chỉ có thể thắng nếu chúng ta hợp sức lại, vì vậy chúng ta phải hỗ trợ họ khi họ đình công. \n=> Việc đình công chưa xảy ra nên ta loại phương án D (quá khứ đơn)\n=> The moment = when. Mênh đề  trạng ngữ chỉ thời gian when không chia thì tương lai nên loại A, B.\nDo đó, đáp án là C","options":{"A":"will have gone","B":"will go","C":"go","D":"went"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/47","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":46,"question_number":47,"question_type":"choice","question_text":"I am sorry. I_____that fellow’s name already.","answer":"B","explanation":"Căn cứ: “already” là dấu hiệu nhận biết thì hiện tại hoàn thành.\u000b- Dịch nghĩa: Tôi xin lỗi. Tôi đã quên tên đồng nghiệp đó rồi.","options":{"A":"forgot","B":"have forgotten","C":"have been forgetting","D":"forget"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/48","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":47,"question_number":48,"question_type":"choice","question_text":"It usually_____very much in that part of the United States.","answer":"C","explanation":"Căn cứ: “usually” là dấu hiệu nhận biết thì hiện tại đơn.\u000b- Dịch nghĩa: Trời thường mưa nhiều ở phần kia của nước Mỹ.","options":{"A":"is raining","B":"rained","C":"rains","D":"have rained"}},
{"id":"chuyen-de-thi-dong-tu/exercise/4/q/49","exercise_id":"chuyen-de-thi-dong-tu/exercise/4","position":48,"question_number":49,"question_type":"choice","question_text":"Look! A man_____after the train. He wants to catch it.","answer":"D","explanation":"Căn cứ: “Look! ” là dấu hiệu nhận biết thì hiện tại tiếp diễn.\u000b- Dịch nghĩa: Nhìn kìa! Một người đàn ông đang chạy sau tàu hỏa. Anh ấy muốn bắt kịp nó.","options":{"A":"runs","B":"have been running","C":"will run","D":"is running TEST I"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":0,"question_number":1,"question_type":"choice","question_text":"Hoang_____his email four times a week in order not to miss anything important.","answer":"A","explanation":"Giải thích: ta có cụm “four times a week” = bốn lần trong tuần, chỉ tần xuất công việc được làm → sử dụng thì hiện tại đơn.\u000bDịch: Hoàng kiểm tra email bốn lần trong tuần để không bỏ lỡ bất kì thứ gì quan trọng","options":{"A":"checks","B":"will check","C":"is checking","D":"check"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":1,"question_number":2,"question_type":"choice","question_text":"Nowadays, people_____social networks with more and more caution.","answer":"D","explanation":"Giải thích: Ta có trạng từ “nowadays”: ngày nay-> diễn tả thời điểm trong thời điểm hiện tại về một xu thế thịnh thành -> ta dùng thì hiện tại đơn\n*Ta không dùng đáp án B vì nó không phải là hành động xảy ra tại thời điểm nói, mà nó được xem như một sự thật trong thời điểm hiện tại và về sau nữa.\u000bDịch: Ngày nay, mọi người sử dụng mạng xã hội càng thận trọng hơn.","options":{"A":"uses","B":"are using","C":"used","D":"use"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":2,"question_number":3,"question_type":"choice","question_text":"At the moment, my sister_____her homework, my brother_____games.","answer":"B","explanation":"Giải thích: “at the moment” là dấu hiệu nhận biết thì hiện tại tiếp diễn, hai hành động diễn ra song song → thì hiện tại tiếp diễn\n+ Ta dùng cụm từ cố định: Do homework: làm bài tập về nhà\u000bDịch: Ngay lúc này, chị tôi đang làm bài tập về nhà và em trai tôi đang chơi trò chơi điện tử.","options":{"A":"is making - is playing","B":"is doing - is playing","C":"does - plays","D":"makes - is playing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":3,"question_number":4,"question_type":"choice","question_text":"It’s 7.00 p.m. now and we_____meal together. We usually_____dinner at that time.","answer":"C","explanation":"Giải thích: “7.00 p.m. now” → một điểm thời gian nhất định trong hiện tại → thì hiện tại tiếp diễn.\u000b“usually” → dấu hiệu nhận biết thì hiện đơn\u000bDịch: Bây giờ là 7 giờ tối và chúng tôi đang ăn tối với nhau. Chúng tôi thường ăn tối vào giờ này.","options":{"A":"have - eat","B":"have - are eating","C":"are having - eat","D":"are having - are eating"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":4,"question_number":5,"question_type":"choice","question_text":"I_____a bike to school every day but today I_____to school by bus because it was stolen yesterday.","answer":"B","explanation":"Tạm dịch: Hàng ngày tôi đi xe đạp đến trường nhưng hôm nay tôi đến trường bằng xe buýt bởi vì xe đạp của tôi bị mất trộm hôm qua. \n- Diễn tả thói quen ta chia thì hiện tại đơn -> ride\n-Thay đổi của thói quen ta chia thì hiện tại tiếp diễn -> am going","options":{"A":"rode - went","B":"ride - am going","C":"ride - go","D":"is riding - am going"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":5,"question_number":6,"question_type":"choice","question_text":"That Hoa_____in class affects other students around.","answer":"B","explanation":"Giải thích: \n- thì hiện tại tiếp diễn dùng để diễn tả sự kêu ca, phàn nàn ( be + always + Ving)\u000bDịch: Việc Hoa thường xuyên nói chuyện trong lớp ảnh hưởng đến các bạn xung quanh.","options":{"A":"always talk","B":"is always talking","C":"always talks","D":"always talking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":6,"question_number":7,"question_type":"choice","question_text":"Hoang and Phong_____football as they’re having class now.","answer":"D","explanation":"Giải thích:\u000b- Căn cứ vào \" now\" => chia thì hiện tại tiếp diễn\u000bDịch: Hoàng và Phong không đá bóng bây giờ vì họ đang phải học.","options":{"A":"don’t play","B":"are playing","C":"doesn’t play","D":"aren’t playing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":7,"question_number":8,"question_type":"choice","question_text":"Hoa usually_____charge of doing the washing-up in her family.","answer":"A","explanation":"Giải thích: “usually” trạng từ chỉ tần xuất, dấu hiệu nhận biết thì hiện tại đơn.\u000bTake charge: chịu trách nhiệm\u000bDịch: Hoa thường chịu trách nhiệm việc rửa bát trong gia đình cô ấy.","options":{"A":"takes","B":"is taking","C":"take","D":"will take"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":8,"question_number":9,"question_type":"choice","question_text":"Our friends_____for the fashion show now.","answer":"B","explanation":"Giải thích: “now” là dấu hiệu nhận biết thì hiện tại tiếp diễn\u000bDịch: Bạn của chúng tôi đang chuẩn bị cho một buổi biểu diễn thời trang bây giờ.","options":{"A":"is preparing","B":"are preparing","C":"prepares","D":"prepare"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":9,"question_number":10,"question_type":"choice","question_text":"All staff in this restaurant_____an urgent meeting right now.","answer":"A","explanation":"Giải thích: “right now”: ngay bây giờ → dấu hiệu nhận biết thì hiện tại tiếp diễn.\u000bDịch: Tất cả nhân viên của nhà hàng này đang có mặt tại một cuộc họp khẩn ngay bây giờ.","options":{"A":"are attending","B":"is attending","C":"attends","D":"attend"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":10,"question_number":11,"question_type":"choice","question_text":"After the physics lesson, the children know that water_____at 100 Degrees","answer":"C","explanation":"Giải thích: \n- thì hiện tại đơn dùng để diễn tả chân lí, sự thật đúng\n- căn cứ vào “water” là danh từ không đếm được nên động từ chia ở số ít\u000bDịch: Sau tiết học môn vật lý, bọn trẻ biết rằng nước sôi ở mức 100 độ C.","options":{"C":"boils","A":"will boil","B":"is boiling","D":"boil"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":11,"question_number":12,"question_type":"choice","question_text":"My mom_____to the supermarket every Sunday for shopping.","answer":"A","explanation":"Giải thích: “every Sunday” chỉ tần suất thực hiện hành động → hiện tại đơn\u000bDịch: Mẹ tôi đi siêu thị chủ nhật hành tuần để mua đồ.","options":{"A":"goes","B":"go","C":"is going","D":"are going"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":12,"question_number":13,"question_type":"choice","question_text":"Look! Minh_____on stage. She looks so beautiful.","answer":"C","explanation":"Giải thích: Động từ chỉ hình thái “Look” → hiện tại tiếp diễn\u000bDịch: Nhìn kìa! Minh đang hát trên sân khấu. Cô ấy trông thật xinh đẹp.","options":{"A":"sings","B":"are singing","C":"is singing","D":"sang"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":13,"question_number":14,"question_type":"choice","question_text":"Bich sometimes_____chicken noodle soup for breakfast.","answer":"D","explanation":"Giải thích: trạng từ tần xuất “sometimes”, hành động mô tả một thói quen → hiện tại đơn.\u000bDịch: Bích thỉnh thoảng ăn phở gà vào bữa sáng.","options":{"A":"are having","B":"is having","C":"have","D":"has"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":14,"question_number":15,"question_type":"choice","question_text":"Who_____the guitar in that room, Hoa?","answer":"B","explanation":"Giải thích: một hành động đang diễn ra ngay tại thời điểm nói → hiện tại tiếp diễn\u000bDịch: Ai đàn chơi đàn ghi-ta trong phòng đó vậy, Hoa?","options":{"A":"playing","B":"is playing","C":"play","D":"plays"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/16","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":15,"question_number":16,"question_type":"choice","question_text":"Jenny often_____jeans and T-shirt at school but she_____a gorgeous dress today.","answer":"A","explanation":"Giải thích: Mệnh đề đầu tiên có trạng từ tần xuất “often” →hiện tại đơn\u000bMệnh đề sau “but” có trạng từ thời gian “today”, sự việc được nói đến trong khoảng thời gian xung quanh thời điểm nói → hiện tại tiếp diễn","options":{"A":"wears - is wearing","B":"is wearing - wears","C":"wear - is wearing","D":"wears - wears"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/17","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":16,"question_number":17,"question_type":"choice","question_text":"First thing in the morning, I_____a cup of milk tea.","answer":"C","explanation":"Giải thích: “First thing in the morning” = điều đầu tiên trong buổi sáng → chỉ một thói quen → hiện tại đơn.\u000bDịch: Điều đầu tiên trong buổi sáng, tôi uống một cốc trà sữa.","options":{"A":"has","B":"am having","C":"have","D":"will have"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/18","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":17,"question_number":18,"question_type":"choice","question_text":"Ms. Kim_____very well when she’s under pressure.","answer":"D","explanation":"Giải thích: Mệnh đề sau “when” là hiện tại đơn, diễn tả một đặc điểm, tính chất của con người/sự vật/hiện tượng → hiện tại đơn\u000bDịch: Cô Kim làm việc không tốt khi cô ấy bị áp lực.","options":{"A":"not work","B":"don’t work","C":"isn’t working","D":"doesn’t work"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/19","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":18,"question_number":19,"question_type":"choice","question_text":"I’m sorry. Lan is busy now. She_____her document on the second floor.","answer":"D","explanation":"Giải thích: có “now” ở mệnh đề đầu → hiện tại tiếp diễn\u000bDịch: Tôi xin lỗi, Lan đang bây giờ đang bận. Cô ấy đang kiểm tra tài liệu ở tầng hai.","options":{"A":"are checking","B":"check","C":"checks","D":"is checking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/20","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":19,"question_number":20,"question_type":"choice","question_text":"Hurry up, Linh. Other friends_____for us.","answer":"A","explanation":"Giải thích: “Hurry up” = nhanh lên → lời thúc giục → hiện tại tiếp diễn\u000bDịch: Nhanh lên, Linh. Những bạn khác đang đợi chúng ta.","options":{"A":"are waiting","B":"waits","C":"wait","D":"is waiting"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/21","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":20,"question_number":21,"question_type":"choice","question_text":"My clothes are not in the room. They_____them away.","answer":"B","explanation":"Giải thích: Hành động đã xảy ra và còn để lại kết quả ở hiện tại → hiện tại hoàn thành\u000bDịch: Quần áo của tôi không còn trong phòng. Họ vừa đem chúng đi rồi.","options":{"A":"take","B":"have taken","C":"took","D":"are taking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/22","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":21,"question_number":22,"question_type":"choice","question_text":"She_____for 10 hours! You must wake her up.","answer":"C","explanation":"Giải thích: Hành động đã xảy ra trong quá khứ vã vẫn đang tiếp tục xảy ra ở hiện tại trong một khoảng thời gian dài → hiện tại hoàn thành tiếp diễn\u000bDịch: Cô ấy đã ngủ được 10 tiếng đồng hồ rồi. Bạn cần gọi cô ấy dậy.","options":{"A":"sleeps","B":"is sleeping","C":"has been sleeping","D":"slept"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/23","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":22,"question_number":23,"question_type":"choice","question_text":"David_____the TV set at the moment. He_____at it for one hour or so.","answer":"A","explanation":"Giải thích: Mệnh đề đầu: “at the moment” → dấu hiệu nhận biết thì hiện tại tiếp diễn → loại B,C,D.\u000bMệnh đề sau: sử dụng hiện tại hoàn thành mô tả hành động đã xảy ra trong quá khứ kéo dài đến hiện tại, dấu hiệu nhận biết “for one hour or so”.\u000bDịch: David đang chữa đầu TV. Anh đã phải sửa nó được 1 tiếng đồng hồ hoặc hơn.","options":{"A":"is repairing/ has worked","B":"repairs/has been working","C":"has repaired/has been working","D":"repairs/worked"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/24","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":23,"question_number":24,"question_type":"choice","question_text":"David_____his hands. He just_____the TV set.","answer":"C","explanation":"Giải thích: Mệnh đề đầu: hành động đang diễn ra tại thời điểm nói.\u000bMệnh đề sau: “just” → dấu hiệu nhận biết hiện tại hoàn thành. Hành động sửa TV đã xảy ra và vừa mới có kết quả ở hiện tại.\u000bDịch: David đang rửa tay. Anh ấy vừa mới sửa ti vi.","options":{"A":"washes/has just repaired","B":"is washing/has just been repairing","C":"is washing/ has just repaired","D":"has washed/ has just repaired"}},
{"id":"chuyen-de-thi-dong-tu/exercise/5/q/25","exercise_id":"chuyen-de-thi-dong-tu/exercise/5","position":24,"question_number":25,"question_type":"choice","question_text":"Why_____?_____you his anecdotes?","answer":"B","explanation":"Giải thích: + Hành động mọi người đang cười xảy ra ngay tại thời điểm nói → hiện tại tiếp diễn. \n+ Câu chuyện đó đã được kể và để lại kết quả hiện tại → chia hiện tại hoàn thành. Tuy nhiên, ở đây nhằm ý nhấn mạnh quá trình của hành động “kể chuyện” nó kéo dài từ trước, cho đến khi có hành động “cười” nên ta dùng thì hiện tại hoàn thành tiếp diễn.\u000bDịch: Tại sao tất cả mọi người đều cười? Jim vừa kể câu chuyện vặt của anh ta à?","options":{"A":"are you laughing/has Jim told","B":"are you laughing/has Jim been telling","C":"have you laughed/ has Jim told","D":"have you laughed/ has Jim been telling"}},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":0,"question_number":1,"question_type":"fill","question_text":"I_____(lose) my key yesterday.","answer":"lost","explanation":"Căn cứ vào dấu hiệu của thì quá khứ đơn: yesterday. – Dịch: Tôi đã mất chìa khóa của mình ngày hôm qua.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":1,"question_number":2,"question_type":"fill","question_text":"People_____(build) this school in 2001.","answer":"built","explanation":"Căn cứ vào dấu hiệu của thì quá khứ đơn: in + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":2,"question_number":3,"question_type":"fill","question_text":"Last year, my father_____(promise) to buy my sister a piano. She_____(be) very delighted to hear this.","answer":"promised","explanation":"Căn cứ vào dấu hiệu của thì quá khứ đơn: Last + night/ week/ year.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":3,"question_number":4,"question_type":"fill","question_text":"It_____(be) very hot last summer.","answer":"was","explanation":"Căn cứ vào: “last summer” là dấu hiệu của thì quá khứ đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":4,"question_number":5,"question_type":"fill","question_text":"I_____(walk) home after the party last night.","answer":"walked","explanation":"Căn cứ vào: “last night” là dấu hiệu của thì quá khứ đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":5,"question_number":6,"question_type":"fill","question_text":"The Chinese_____(invent) printing.","answer":"invented","explanation":"Căn cứ vào cách dùng của thì quá khứ đơn: diễn tả các sự việc đã xảy ra trong quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":6,"question_number":7,"question_type":"fill","question_text":"Sam and I_____(play) tennis yesterday. He was much better than I was, so he_____(win) easily.","answer":"played","explanation":"Căn cứ vào dấu hiệu của thì quá khứ đơn: yesterday.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":7,"question_number":8,"question_type":"fill","question_text":"My grandpa_____(die) 30 years ago. I never_____(meet) him.","answer":"died / met","explanation":"Căn cứ vào trạng từ thời gian của thì quá khứ đơn “ago” nên ta chia: die -> died. - Vì ông đã mất từ 30 năm trước nên không bao giờ gặp được ông nữa nên vế sau ta chia ở quá khứ đơn. Vì hành động “không thể gặp” nó cũng đã diễn ra trong quá khứ, cùng với hành động kể lại một trải nghiệm đã qua nên ta chia quá khứ đơn cho cả hai vế. meet-> met – Dịch: Ông tôi đã mất 30 năm trước. Tôi chưa bao giờ gặp ông.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":8,"question_number":9,"question_type":"fill","question_text":"- You_____(go) to the movies last night? - Yes, but it_____(be) a mistake. The movie_____(be) awful.","answer":"Did you go","explanation":"* Căn cứ vào: - “last night” là dấu hiệu của thì quá khứ đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":9,"question_number":10,"question_type":"fill","question_text":"When I_____(get) home last night, I_____(be) very tired, so I _____(go) straight to the bed.","answer":"got","explanation":"Căn cứ vào: “last night” là dấu hiệu của thì quá khứ đơn. + “thì quá khứ đơn” dùng để diễn tả những hành động xảy ra liên tiếp trong quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":10,"question_number":11,"question_type":"fill","question_text":"Diane_____(use) to travel a lot. These days she doesn’t take many trips.","answer":"used","explanation":"Căn cứ vào cách dùng của USED TO + V: diễn tả thói quen trong quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":11,"question_number":12,"question_type":"fill","question_text":"- When Joe and Carol_____(meet) each other? - They first_____(meet) when they_____(be) in high school.","answer":"did …. meet/met/were","explanation":"Dịch: - Joe và Carol gặp nhau khi nảo? - Họ gặp nhau lần đầu khi họ còn học ở phổ thông. => Tất cả các hành động đã xảy ra và đã kết thúc trong quá khứ nên ta chia ở thì quá khứ đơn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":12,"question_number":13,"question_type":"fill","question_text":"When Sarah_____(get) to the party last night, Eric had already gone home.","answer":"got","explanation":"Căn cứ vào mệnh đề trạng ngữ chỉ thời gian: When S + V (quá khứ đơn), S + V (quá khứ hoàn thành).","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":13,"question_number":14,"question_type":"fill","question_text":"I_____(ring) you up two days ago but I_____(get) no answer. Where you_____(be)?","answer":"rang","explanation":"Căn cứ vào dấu hiệu của thì quá khứ đơn: “two days ago”.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/6/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/6","position":14,"question_number":15,"question_type":"fill","question_text":"When I_____(be) small, I often_____(play) with a doll.","answer":"was","explanation":"Căn cứ vào mệnh đề trạng ngữ chỉ thời gian: when S + V (quá khứ đơn), S + V (quá khứ đơn) (kể về một hồi ức)","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":0,"question_number":1,"question_type":"fill","question_text":"This time last year I_____(live) in Brazil.","answer":"was living","explanation":"Căn cứ vào dấu hiệu của thì quá khứ tiếp diễn: this time + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":1,"question_number":2,"question_type":"fill","question_text":"What you_____(do) at 10:00 last night?","answer":"What were you doing……","explanation":"Căn cứ vào dấu hiệu của thì quá khứ tiếp diễn- xảy ra tại một thời điểm cụ thể trong quá khứ: at 10:00 + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":2,"question_number":3,"question_type":"fill","question_text":"At that time yesterday, I_____(write) a letter.","answer":"was writing","explanation":"Căn cứ vào dấu hiệu của thì quá khứ tiếp diễn: at that time + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":3,"question_number":4,"question_type":"fill","question_text":"She_____(learn) English at school at 7:45 yesterday morning.","answer":"was learning","explanation":"Căn cứ vào dấu hiệu của thì quá khứ tiếp diễn: at 7:45 yesterday morning + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":4,"question_number":5,"question_type":"fill","question_text":"- What you_____(do) at this time last night? - I was asleep.","answer":"were","explanation":"Căn cứ vào dấu hiệu của thì quá khứ tiếp diễn: at that time + mốc thời gian quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":5,"question_number":6,"question_type":"fill","question_text":"Matt burned his hand while he_____(cook) lunch.","answer":"was cooking","explanation":"Căn cứ vào cách dùng của thì quá khứ tiếp diễn: một hành động xảy ra thì có một hành động khác xen vào.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":6,"question_number":7,"question_type":"fill","question_text":"I saw you in the park yesterday. You_____(sit) on the grass and _____(read) a book.","answer":"were sitting / reading | were sitting / were reading","explanation":"Căn cứ vào ngữ cảnh của câu ta chia thì quá khứ tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":7,"question_number":8,"question_type":"fill","question_text":"When I came home, my mother_____(prepare) the meal.","answer":"was preparing","explanation":"* Căn cứ vào sự phối thì giữa thì quá khứ đơn và quá khứ tiếp diễn: - when S + V(quá khứ đơn), S + V(quá khứ tiếp diễn). ( Dùng để diễn tả hành động đang xảy ra thì có hành động khác xen vào). * Dịch nghĩa: Khi tôi về nhà, mẹ tôi đang chuẩn bị bữa ăn. => “nấu ăn” là hành động đang xảy ra => chia thì quá khứ tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":8,"question_number":9,"question_type":"fill","question_text":"Jane_____(wait) for me when I arrived.","answer":"was waiting","explanation":"Căn cứ vào cách dùng của thì quá khứ tiếp diễn: một hành động xảy ra thì có một hành động khác xen vào.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":9,"question_number":10,"question_type":"fill","question_text":"Yesterday evening, while my mother_____(cook) in the kitchen, my father_____(watch) the news on TV.","answer":"was cooking","explanation":"Căn cứ vào cách dùng của thì quá khứ tiếp diễn khi có “while” và “yesterday evening”: diễn tả hai hành động xảy ra song song cùng lúc trong quá khứ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":10,"question_number":11,"question_type":"fill","question_text":"Just as I_____(leave) the house, I heard an explosion from the inside the lab.","answer":"was leaving","explanation":"Căn cứ vào cách dùng của thì quá khứ tiếp diễn: một hành động xảy ra thì có một hành động khác xen vào.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":11,"question_number":12,"question_type":"fill","question_text":"When Beth arrived, we_____(have) dinner.","answer":"were having","explanation":"Căn cứ vào ngữ cảnh của câu ta chia thì quá khứ tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":12,"question_number":13,"question_type":"fill","question_text":"Why didn’t you listen to me while I (talk)_____with you?","answer":"was talking","explanation":"* Dịch nghĩa: Tại sao bạn không lắng nghe tôi trong khi tôi nói chuyện với bạn?","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":13,"question_number":14,"question_type":"fill","question_text":"Michiko couldn’t come to the phone when the director called her because she_____(work) in the factory.","answer":"was working","explanation":"* Dịch: Michiko không thể đến nghe điện thoại khi giám đốc gọi cô ấy bởi vì cô ấy đang làm việc trong nhà máy. * Căn cứ: cách dùng của thì quá khứ tiếp diễn: - Diễn đạt hành động đang xảy ra tại thời điểm trong quá khứ. - Giám đốc gọi khi “cô ấy đang làm việc” -> cô ấy không nghe máy.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/7/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/7","position":14,"question_number":15,"question_type":"fill","question_text":"I_____(enjoy) the party, but Chris wanted to go home.","answer":"was enjoying","explanation":"* Dịch nghĩa: Tôi đang thưởng thức bữa tiệc, nhưng Chris muốn về nhà. * Căn cứ cách dùng của thì quá khứ tiếp diễn: - Diễn tả hành động đang xảy ra thì có hành động khác xen vào. + thưởng thức bữa tiệc bị hành động Chris muốn về nhà xen vào. => chia thì quá khứ tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":0,"question_number":1,"question_type":"fill","question_text":"Before Sarah arrived, Eric_____(go) home.","answer":"had gone","explanation":"Căn cứ vào cấu trúc của “before” đi với thì quá khứ hoàn thành: Before S + V (quá khứ đơn), S + V (quá khứ hoàn thành). Vế chứa “before” chia quá khứ đơn => vế còn lại chia quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":1,"question_number":2,"question_type":"fill","question_text":"When Jane arrived at the theater, the film_____(start).","answer":"had started","explanation":"Dịch: Khi Jane đến rạp chiếu phim, bộ phim đã bắt đầu rồi. => Diễn tả hành động xảy ra xong trước một hành động khác trong quá khứ ta chia thì quá khứ hoàn thành. *Note: Hành động “start” một bộ phim nó không thể chia ở thì tiếp diễn trong ngữ cảnh này, vì thế không thể chia theo dạng “một hành động đang diễn ra thì có một hành động khác chen vào”, nên không chia vị trí trống này ở dạng quá khứ tiếp diễn được.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":2,"question_number":3,"question_type":"fill","question_text":"He thanked me for everything I_____(do) for him.","answer":"had done","explanation":"* Dịch nghĩa: Anh ấy cảm ơn tôi vì mọi thứ tôi đã làm cho anh ấy. * Căn cứ vào: - Hành động làm mọi thứ cho anh ấy diễn ra trước việc cảm ơn. => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":3,"question_number":4,"question_type":"fill","question_text":"After Angelia_____(eat) the cake, she began to feel sick.","answer":"had eaten","explanation":"Căn cứ vào với cấu trúc của “after” đi với thì quá khứ hoàn thành: After S + V (quá khứ hoàn thành), S + V (quá khứ đơn). Về không chứa “after” chia quá khứ đơn => về còn lại chia quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":4,"question_number":5,"question_type":"fill","question_text":"When he went out to play, he_____(do already) his homework.","answer":"had already done","explanation":"Căn cứ vào cấu trúc của “when” đi với thì quá khứ hoàn thành: When S + V (quá khứ đơn), S + V (quá khứ hoàn thành). Vế chứa “when” chia thì quá khứ đơn => Vế còn lại chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":5,"question_number":6,"question_type":"fill","question_text":"They_____(be) married for two years or so when Roy employed a very attractive Indian secretary in his Glasgow office.","answer":"had been","explanation":"Dịch nghĩa: Lúc mà Roy thuê một thư kí hấp dẫn người Ấn Độ trong văn phòng Glassgow của ông ấy thì họ đã kết hôn được hai năm hoặc hơn. + việc “kết hôn” xảy ra trước việc “thuê thư kí” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":6,"question_number":7,"question_type":"fill","question_text":"Linda_____(not study) for the exam, so she was very anxious.","answer":"had not studied","explanation":"Căn cứ vào cách dùng của thì quá khứ hoàn thành: Khi hai hành động cùng xảy ra trong quá khứ, ta dùng thì quá khứ hoàn thành cho hành động xảy ra trước và quá khứ đơn cho hành động xảy ra sau. Hành động xảy ra trước “không học tập chăm chỉ” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":7,"question_number":8,"question_type":"fill","question_text":"I couldn’t go into the cinema because I_____(not bring) my tickets.","answer":"hadn’t brought","explanation":"Căn cứ vào cách dùng của thì quá khứ hoàn thành: Khi hai hành động cùng xảy ra trong quá khứ, ta dùng thì quá khứ hoàn thành cho hành động xảy ra trước và quá khứ đơn cho hành động xảy ra sau. Hành động xảy ra trước “không mang theo vé” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":8,"question_number":9,"question_type":"fill","question_text":"The man sitting next to me on the plane was very nervous. He never _____(fly) before.","answer":"had never flown","explanation":"Căn cứ vào dấu hiệu của thì hiện tại hoàn thành: before. - Căn cứ vào động từ “was” ở câu thứ nhất => Hành động “chưa từng bay” tính tới thời điểm \" lo lắng“. Mà hành động ”lo lắng\" chia ở quá khứ đơn thì hành động \" chưa từng bay\" phải xảy ra trước quá khứ đơn => chia quá khứ hoàn thành. – Dịch: Người đàn ông đang ngồi cạnh tôi trên máy bay rất lo lắng. Anh ấy chưa từng bay trước đó.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":9,"question_number":10,"question_type":"fill","question_text":"The tornado knocked down the tree that we_____(plant).","answer":"had planted","explanation":"Căn cứ vào cách dùng của thì quá khứ hoàn thành: Khi hai hành động cùng xảy ra trong quá khứ, ta dùng thì quá khứ hoàn thành cho hành động xảy ra trước và quá khứ đơn cho hành động xảy ra sau. Hành động xảy ra trước “trồng cây” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":10,"question_number":11,"question_type":"fill","question_text":"Laura_____(not/use) smartphone before, so I showed her how to use it.","answer":"hadn’t used","explanation":"Căn cứ vào cách dùng của thì quá khứ hoàn thành: Khi hai hành động cùng xảy ra trong quá khứ, ta dùng thì quá khứ hoàn thành cho hành động xảy ra xong trước và quá khứ đơn cho hành động xảy ra sau. Hành động xảy ra trước “không sử dụng điện thoại trước đây” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":11,"question_number":12,"question_type":"fill","question_text":"We weren’t hungry. We_____(just have) lunch.","answer":"had just had","explanation":"Căn cứ vào cách dùng của thì quá khứ hoàn thành: Khi hai hành động cùng xảy ra trong quá khứ, ta dùng thì quá khứ hoàn thành cho hành động xảy ra trước và quá khứ đơn cho hành động xảy ra sau. Hành động xảy ra trước “đã ăn trưa rồi” => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":12,"question_number":13,"question_type":"fill","question_text":"We didn’t really want to go and see the film again. We_____(already see) it twice - so we said “no” and we went to a shopping mall instead!","answer":"had already seen","explanation":"Dịch nghĩa: Chúng tôi thực sự không muốn đi xem bộ phim đó nữa. Chúng tôi đã xem nó hai lần vì vậy chúng tôi nói “không”, thay vào đó chúng tôi đi mua sắm. Căn cứ vào: - đã xem phim đó hai lần => nhấn mạnh việc này đã xảy ra trước => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":13,"question_number":14,"question_type":"fill","question_text":"When thieves stole my favorite feather wallet, I was really upset. I _____(have) it for over five years.","answer":"had been having","explanation":"Dịch nghĩa: Khi những tên trộm lấy cắp ví lông yêu thích của tôi, tôi đã rất buồn. Tôi đã dùng nó hơn năm năm rồi. - Giải thích: Ta thấy việc sử dụng chiếc ví trong 5 năm xảy ra trước hành động tên trộm lấy trộm, mà hành động “lấy trộm” chia quá khứ đơn thì hành động “sử dụng ví” xảy ra trước quá khứ; đồng thời ta căn cứ vào quãng thời gian “for over five years”, ta dùng thì quá khứ hoàn thành tiếp diễn để nhấn mạnh quá trình của hành động.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/8/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/8","position":14,"question_number":15,"question_type":"fill","question_text":"Before going to the meeting, he_____(consult) with his lawyers.","answer":"had consulted","explanation":"* Dịch nghĩa: Trước khi đi đến buổi họp, anh ấy đã hỏi ý kiến những luật sư của mình. * Việc “anh ấy hỏi ý kiến” xảy ra trước việc đến buổi họp. => chia thì quá khứ hoàn thành.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":0,"question_number":1,"question_type":"fill","question_text":"We_____(play) tennis for about an hour when it started to rain heavily.","answer":"had been playing","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - diễn tả hành động xảy ra liên tục kéo dài trước hành động khác trong quá khứ. - hành động xảy ra liên tục kéo dài “chơi quần vợt trong vòng một giờ”. * Dịch nghĩa: Chúng tôi đã chơi quần vợt trong vòng một giờ thì trời bắt đầu mưa lớn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":1,"question_number":2,"question_type":"fill","question_text":"I was very tired when I got home. I_____(work) hard all day.","answer":"had been working","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn tả hành động là nguyên nhân của một điều gì đó trong quá khứ. - Đã làm việc cả ngày -> mệt mỏi khi về nhà. * Dịch nghĩa: Tôi đã rất mệt khi về nhà. Tôi đã làm việc cả ngày.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":2,"question_number":3,"question_type":"fill","question_text":"At last the bus came. He_____(wait) for 20 minutes.","answer":"had been waiting","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn tả hành động xảy ra kéo dài liên tục trước thời điểm xác định trong quá khứ. - Hành động anh ấy “chờ trong vòng 20 phút”, diễn ra liên tục trước khi xe buýt đến. * Dịch nghĩa: Cuối cùng xe buýt đến. Anh ấy đã chờ trong 20 phút.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":3,"question_number":4,"question_type":"fill","question_text":"Jim quit drinking coffee two years ago. He_____(drink) coffee for 20 years.","answer":"had been drinking","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Việc anh ấy uống cà phê trong 20 năm => nhấn mạnh tính kéo dài liên tục của hành động. - Nó xảy ra trước việc anh ấy “bỏ uống cà phê 2 năm trước”. => chia thì QKHT tiếp diễn. * Dịch nghĩa: Jim đã bỏ uống cà phê hai năm trước. Anh ấy đã uống trong vòng 20 năm.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":4,"question_number":5,"question_type":"fill","question_text":"She was out of breath. She_____(run).","answer":"had been running","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn đạt hành động là nguyên nhân của một điều gì đó trong quá khứ - Việc “cô ấy thở hổn hển” xảy ra trong quá khứ và là kết quả của hành động “chạy” nên ta dùng thì QKHT tiếp diễn. * Dịch nghĩa: Cô ấy thở hổn hển. Cô ấy đã chạy.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":5,"question_number":6,"question_type":"fill","question_text":"It wasn’t raining when we went out. The sun was shining. But it_____ (rain), so the ground was wet.","answer":"had been raining","explanation":"* Căn cứ vào: cách dùng của thì quá khứ hoàn thành tiếp diễn - Nhấn mạnh tính liên tục của hành động tính tới trước một hành động khác trong quá khứ - \"mặt đất ướt\" là kết quả của việc \"trời mưa\". Mà hành động đất ẩm ướt chia quá khứ đơn thì hành động trời mưa phải xảy ra trước nên ta chia quá khứ hoàn thành tiếp diễn * Dịch nghĩa: Trời không mưa khi chúng tôi ra ngoài. Mặt trời đang chiếu sáng. Nhưng trời đã mưa, vì vậy mặt đất ướt.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":6,"question_number":7,"question_type":"fill","question_text":"We were extremely tired at the end of our trip. We_____(travel) for more than 24 hours.","answer":"had been travelling","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Nhấn mạnh hành động để lại kết quả trong quá khứ. - Việc cực kì mệt\" ở cuối chuyến đi là kết quả của việc “đã di chuyển hơn 24 tiếng”. => chia thì QKHT tiếp diễn. * Dịch nghĩa: Chúng tôi đã cực kì mệt ở cuối chuyến đi. Chúng tôi đã đi du lịch trong hơn 24 giờ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":7,"question_number":8,"question_type":"fill","question_text":"I was exhausted at the end of the test. I_____(write) for over three hours.","answer":"had been writing","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Nhấn mạnh hành động để lại kết quả trong quá khứ. - Việc \"kệt sức\" đã xảy ra trong quá khứ và là kết quả của việc \"viết trong hơn ba giờ\". * Dịch nghĩa: Tôi đã kiệt sức ở cuối bài kiểm tra. Tôi đã viết trong hơn ba giờ.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":8,"question_number":9,"question_type":"fill","question_text":"The orchestra_____(play) for 30 minutes when a man in audience suddenly began shouting.","answer":"had been playing","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn đạt hành động xảy ra trước hành động khác trong quá khứ. (Nhấn mạnh tính liên tục của hành động). - “trong 30 phút” nhấn mạnh “dành nhạc đã chơi trong 30 phút”. * Dịch nghĩa: Dàn nhạc đang chơi được 30 phút thì một người đàn ông trong số những khán giả bắt đầu la hét.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":9,"question_number":10,"question_type":"fill","question_text":"At the time the factory closed down, Sarah_____(work) there for five years.","answer":"had been working","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Nhấn mạnh hành động đang xảy ra trước một hành động khác trong quá khứ (nhấn mạnh tính tiếp diễn). - “trong vòng 5 năm” nhấn mạnh thời gian “Sarah đã làm việc”. => chia thì QKHT tiếp diễn. * Dịch nghĩa: Vào thời điểm nhà máy đóng cửa, Sarah đã làm việc ở đây trong vòng 5 năm.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":10,"question_number":11,"question_type":"fill","question_text":"- She_____(watch) TV for 4 hours before she went to eat dinner?","answer":"Had","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn tả hành động xảy ra liên tục kéo dài trước một hành động khác trong quá khứ. - “for 4 hours” nhấn mạnh đến hành động “cô ấy đã xem TV trong 4 giờ trước khi ăn tối”. * Dịch nghĩa: Trước khi cô ấy đi ăn tối cô ấy đã xem TV trong 4 giờ phải không?","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":11,"question_number":12,"question_type":"fill","question_text":"She was very upset because I was late and she _____(wait) for a very long time.","answer":"had been waiting","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Dùng để diễn đạt hành động xảy ra kéo dài liên tục trước một hành động khác trong quá khứ. - “for a very long time” nhấn mạnh hành động chờ “rất lâu”. * Dịch nghĩa: Cô ấy đã rất thất vọng bởi vì tôi đến muộn và cô ấy đã chờ rất lâu.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":12,"question_number":13,"question_type":"fill","question_text":"When the boys came into the house, their clothes were dirty, their hair was messy and one of them had a black eye. They_____(fight).","answer":"had been fighting","explanation":"Dịch: Khi những cậu bé bước vào nhà, quần áo của chúng lấm lem, đầu tóc rối bời và một trong số chúng có một mắt bị tím bầm. Chúng đã đánh nhau. => Hành động đánh nhau xảy ra trước hành động bước vào nhà. Mà hành động bước vào nhà chia ở thì quá khứ đơn thì hành động đánh nhau phải chia ở thì quá khứ hoàn thành. => Tuy nhiên, do hành động đánh nhau đã xảy ra xong trước hành động khác trong quá khứ nhưng để lại dấu hiệu ở quá khứ nên ta chia thì quá khứ hoàn thành tiếp diễn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":13,"question_number":14,"question_type":"fill","question_text":"It was a bit discomfort to arrive at their house and found Liz looking so depressed. I think she_____(cry) before I got there.","answer":"had been crying","explanation":"* Căn cứ vào: cách dùng của thì quá khứ hoàn thành tiếp diễn. - Diễn tả hành động xảy ra liên tục kéo dài trước một hành động khác trong quá khứ. - “cô ấy khóc” xảy ra trong quá khứ và xảy ra trước việc “tôi đến đây”. * Dịch nghĩa: Thật là bối rối để đến nhà của họ và thấy Mary đang thất vọng. Tôi nghĩ cô ấy đã khóc rất nhiều trước khi tôi đến đây.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/9/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/9","position":14,"question_number":15,"question_type":"fill","question_text":"I_____(learn) Germany for 4 years and then decided to give it up.","answer":"had been learning","explanation":"* Căn cứ vào: cách dùng của thì QKHT tiếp diễn. - Diễn tả hành động hành động xảy ra liên tục kéo dài trước hành động khác trong quá khứ. - Việc “học tiếng Đức” xảy ra trong quá khứ và xảy ra trước “việc từ bỏ”. => chia thì QKHT tiếp diễn. * Dịch nghĩa: Tôi đã tiếng Đức trong vòng bốn năm và sau đó quyết định từ bỏ nó.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":0,"question_number":1,"question_type":"choice","question_text":"She passed her examination because she_____very hard.","answer":"C","explanation":"Dịch: Cô ấy đã vượt qua kì thi bởi vì cô ấy học tập chăm chỉ.\n=> Do học hành chăm chỉ mới thi đỗ. \n( Diễn đạt hành động là nguyên nhân của một điều gì đó trong quá khứ ta dùng thì quá khứ hoàn thành tiếp diễn.)","options":{"A":"studied","B":"was studying","C":"had been studying","D":"studies"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":1,"question_number":2,"question_type":"choice","question_text":"You_____out last night or were you tired?","answer":"C","explanation":"Dịch: Bạn đã đi đâu tối qua hay bạn mệt?\n- Căn cứ vào “last night” nên động từ chia thì quá khứ đơn","options":{"A":"Did - went","B":"Had - gone","C":"Did - go","D":"Had - been going"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":2,"question_number":3,"question_type":"choice","question_text":"This time yesterday I_____tennis with my classmates.","answer":"B","explanation":"Căn cứ vào: “This time / at this time + mốc thời gian quá khứ” => ta chia thì quá khứ tiếp diễn.\u000b- Dịch nghĩa: Thời điểm này ngày hôm qua, tôi đang chơi quần vợt với những người bạn cùng lớp của tôi.","options":{"A":"played","B":"was playing","C":"had played","D":"would play"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":3,"question_number":4,"question_type":"choice","question_text":"Nicole_____television a lot when she_____sick last year.","answer":"A","explanation":"Xét các đáp án => ở đây chỉ dùng các thì quá khứ. \n=> Nội dung câu này chỉ một hành động lặp đi lặp lại trong một giai đoạn nào đó ở quá khứ, nên ta chỉ dùng thì quá khứ đơn cho cả 2 vế.\n=> Không phân định hành động nào xảy ra trước, hành động nào sau nên không dùng các thì hoàn thành. \n=> Không phải 1 hành động đang xảy ra thì hành động khác chen vào, nên ta không dùng thì tiếp diễn. \n=> Chốt lại ta được đáp án A. \nDịch: Năm ngoái trong lúc bệnh, Nicole xem TV rất nhiều.","options":{"A":"watched - was","B":"had watched - had been","C":"was watching - was","D":"had been watching - was"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":4,"question_number":5,"question_type":"choice","question_text":"Mary_____home when she met Dave.","answer":"D","explanation":"Căn cứ vào: mệnh đề trạng ngữ chỉ thời gian.\u000bS + V (quá khứ tiếp diễn) + when + S+ V (quá khứ đơn).\n(Diễn tả một hành động đang xảy ra trong quá khứ thì có hành động khác xen vào).\u000b- Dịch nghĩa: Khi Mary đang về nhà thì cô ấy gặp Dave.","options":{"A":"came","B":"had come","C":"had been coming","D":"was coming"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":5,"question_number":6,"question_type":"choice","question_text":"The doorbell_____while I_____a shower.","answer":"B","explanation":"Căn cứ vào: mệnh đề trạng ngữ chỉ thời gian.\u000bS + V (quá khứ đơn) + while + S+ V (quá khứ tiếp diễn). \n(Diễn tả một hành động đang xảy ra trong quá khứ thì có hành động khác xen vào).\u000b- Dịch nghĩa: Chuông cửa đã reo lên trong khi tôi đang tắm.","options":{"A":"was ringing - took","B":"rang - was taking","C":"had rung - took","D":"had been ringing - took"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":6,"question_number":7,"question_type":"choice","question_text":"When I was young, I_____to be a pilot.","answer":"A","explanation":"Dịch: Khi tôi còn trẻ, tôi muốn trở thành phi công.\n=> Kể về một hồi ức chia thì quá khứ đơn","options":{"A":"wanted","B":"had wanted","C":"would want","D":"wants"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":7,"question_number":8,"question_type":"choice","question_text":"The war_____out three years ago.","answer":"C","explanation":"Căn cứ vào: “three years ago” là dấu hiệu nhận biết thì quá khứ đơn.\u000b- Dịch nghĩa: Chiến tranh đã nổ ra ba năm trước.","options":{"A":"was breaking","B":"had broken","C":"broke","D":"have been breaking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":8,"question_number":9,"question_type":"choice","question_text":"When he was young, he_____in the army.","answer":"D","explanation":"Dịch: Khi anh ấy còn trẻ, anh ấy đã đã phục vụ trong quân đội.\n=> kể về một hồi ức => chia thì quá khứ đơn","options":{"A":"had been serving","B":"serves","C":"have served","D":"served"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":9,"question_number":10,"question_type":"choice","question_text":"She often goes to school by bike but yesterday she_____by bus.","answer":"A","explanation":"Căn cứ vào: “yesterday” là dấu hiệu nhận biết thì quá khứ đơn. \n=> Đáp án: A. \nDịch nghĩa: Cô ấy thường đến trường bằng xe đạp nhưng ngày hôm qua cô ấy đi xe buýt.","options":{"A":"travelled","B":"have been travelling","C":"had travelled","D":"travels"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":10,"question_number":11,"question_type":"choice","question_text":"He_____a cup of coffee every morning many years ago.","answer":"B","explanation":"Căn cứ vào: “thời gian + ago” là dấu hiệu nhận biết thì quá khứ đơn. \n=> Loại đáp án A ngay vì nó không liên quan gì đến hiện tại. Đó là thói quen xảy ra và kết thúc hoàn toàn trong quá khứ rồi\n- Không dùng thì quá khứ hoàn thành đứng riêng lẻ một mệnh đề như vậy, nó luôn phải đi kèm với một mệnh đề khác hoặc một mốc thời gian khác trong quá khứ, loại C\n- Không có dấu hiệu cụ thể về thời gian trong quá khứ để chia quá khứ tiếp diễn, loại D\n- Dịch nghĩa: Cách đây nhiều năm trước, anh ấy uống một cốc cà phê mỗi buổi sáng.","options":{"A":"have been drinking","B":"drank","C":"had drunk","D":"was drinking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":11,"question_number":12,"question_type":"choice","question_text":"Yesterday she_____to pay me for my helping her but I didn’t accept.","answer":"D","explanation":"Căn cứ vào: “yesterday” là dấu hiệu nhận biết thì quá khứ đơn.\u000b- Dịch nghĩa: Hôm qua cô ấy đề nghị trả tiền cho tôi vì tôi đã giúp cô ấy nhưng tôi đã không chấp nhận.","options":{"A":"will offer","B":"was offering","C":"had offered","D":"offered"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":12,"question_number":13,"question_type":"choice","question_text":"There_____a lot of grass in the garden last summer.","answer":"B","explanation":"Căn cứ vào: “last summer” là dấu hiệu nhận biết thì quá khứ đơn.\u000b- Dịch nghĩa: Có rất nhiều cỏ ở trong vườn hè năm ngoái.","options":{"A":"had been","B":"were","C":"have been","D":"will be"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":13,"question_number":14,"question_type":"choice","question_text":"It’s time we_____something to help him.","answer":"C","explanation":"Căn cứ vào cấu trúc: It’s time + S + V (quá khứ đơn). (Đã đến lúc ai đó phải làm gì).\u000b- Dịch nghĩa: Đã đến lúc chúng ta làm gì đó để giúp đỡ anh ấy.","options":{"A":"will do","B":"had done","C":"did","D":"was doing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":14,"question_number":15,"question_type":"choice","question_text":"Mr Brown_____in Paris when the Second World War broke out.","answer":"B","explanation":"Dịch: Khi chiến tranh thế giới thứ hai nổ ra, ông Brown đang sống ở Paris. \n=> Diễn tả hành động đang xảy ra thì có hành động khác xen vào. Hành động “sống”xảy ra trước nên ta chia thì quá khứ tiếp diễn.","options":{"A":"lived","B":"was_____living","C":"had lived","D":"will live"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/16","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":15,"question_number":16,"question_type":"choice","question_text":"I and my mom_____comic at this time last night.","answer":"D","explanation":"Căn cứ vào: “at this time last night” là dấu hiệu nhận biết thì quá khứ tiếp diễn.\n- Dịch nghĩa: Vào thời điểm này tối qua tôi và mẹ tôi đang đọc truyện tranh.","options":{"A":"read","B":"had been reading","C":"have read","D":"were reading"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/17","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":16,"question_number":17,"question_type":"choice","question_text":"At lO.pm last night, my younger brother_____games online.","answer":"B","explanation":"Căn cứ vào: “At + giờ + mốc thời gian quá khứ” là dấu hiệu nhận biết thì quá khứ tiếp diễn.\u000b- Dịch nghĩa: Vào lúc 10 giờ tối qua, em trai nhỏ của tôi đang chơi trò chơi điện tử trực tuyến.","options":{"A":"had been playing","B":"was playing","C":"will be playing","D":"have been playing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/18","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":17,"question_number":18,"question_type":"choice","question_text":"People_____all trees along the streets at this time two years ago.","answer":"C","explanation":"Căn cứ vào: “at this time two years ago” là dấu hiệu nhận biết thì quá khứ tiếp diễn.\u000b- Dịch nghĩa: Mọi người đã trồng tất cả các cây trên đường phố vào thời điểm này hai năm trước.","options":{"A":"are planting","B":"will have been planting","C":"were planting","D":"will be planting"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/19","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":18,"question_number":19,"question_type":"choice","question_text":"She_____her homework at this time yesterday morning?","answer":"A","explanation":"Căn cứ vào: dấu hiệu nhận biết thì quá khứ tiếp diễn “at this time yesterday morning”. \n(At this time + mốc thời gian trong quá khứ)\u000b- Dịch nghĩa: Cô ấy đang làm bài tập về nhà thời điểm này sáng ngày hôm qua phải không?","options":{"A":"Was-doing","B":"Had - been doing","C":"Do-do","D":"Will - be doing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/20","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":19,"question_number":20,"question_type":"choice","question_text":"They_____dinner when we_____.","answer":"D","explanation":"Căn cứ vào: cách phối thì giữa thì quá khứ đơn và quá khứ tiếp diễn: Dùng để diễn tả một hành động đang xảy ra thì có hành động khác xen vào trong quá khứ.\u000b- Dịch nghĩa: Họ đang ăn tối thì chúng tôi đến.","options":{"A":"had - was coming","B":"had had - came","C":"come - will be coming","D":"were having - came"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/21","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":20,"question_number":21,"question_type":"choice","question_text":"At 8.am yesterday they_____dinner while we_____TV.","answer":"B","explanation":"Căn cứ vào: dấu hiệu nhận biết thì quá khứ tiếp diễn.\u000bAt + giờ + mốc thời gian quá khứ.\u000b- Dịch nghĩa: Vào lúc tám giờ ngày hôm qua, trong khi chúng tôi đang xem TV thì họ đang ăn tối.","options":{"A":"will be having - will be watching","B":"were having - were watching","C":"are having - are watching","D":"will have had - will have watched"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/22","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":21,"question_number":22,"question_type":"choice","question_text":"When I went out, the sun_____.","answer":"C","explanation":"Dịch: Khi tôi ra ngoài, trời đang bừng nắng.\nGiái thích:\n- hành động mặt trời đang bừng nắng xảy ra trước hành động tôi ra ngoài. Vào lúc tôi ra ngoài thì mặt trời vẫn còn đang bừng nắng => chia thì quá khứ tiếp diễn\nĐáp án C","options":{"A":"will be shining","B":"is shining","C":"was shining","D":"had been shining"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/23","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":22,"question_number":23,"question_type":"choice","question_text":"We_____to the station when it_____to rain.","answer":"A","explanation":"Căn cứ vào: cách dùng của thì quá khứ tiếp diễn: Diễn đạt hành động đang xảy ra thì có hành động khác xen vào.\u000b=> Hành động “đi bộ” đang diễn ra => chia quá khứ tiếp diễn\n=> Hành động “mưa” xen vào => chia quá khứ đơn\u000b- Dịch nghĩa: Chúng tôi đang đi bộ đến nhà ga thì trời mưa.","options":{"A":"were walking - began","B":"had been walking - began","C":"have been walking - begins","D":"will be walking - begin"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/24","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":23,"question_number":24,"question_type":"choice","question_text":"The servant dropped two cups while she_____up last night.","answer":"D","explanation":"Căn cứ vào: cách dùng của thì quá khứ tiếp diễn: Diễn đạt hành động đang xảy ra thì có hành động khác xen vào.\u000b- Dịch nghĩa: Người phục vụ đã làm rơi hai chiếc cốc trong khi cô ấy đang rửa bát tối qua.","options":{"A":"is washing","B":"had been washing","C":"have been washing","D":"was washing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/25","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":24,"question_number":25,"question_type":"choice","question_text":"Almost everybody_____by the time we arrived.","answer":"B","explanation":"Căn cứ: mệnh đề trạng ngữ chỉ thời gian. \nBy the time + S + V (quá khứ đơn), S + V (quá khứ hoàn thành).\n- Dịch nghĩa: Hầu hết mọi người đã rời đi vào vào thời điểm chúng tôi đến.","options":{"A":"have been leaving","B":"had left","C":"was leaving","D":"have left"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/26","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":25,"question_number":26,"question_type":"choice","question_text":"The secretary_____until she_____her work.","answer":"C","explanation":"Dịch nghĩa: Thư kí sẽ không rời đi cho đến khi cô ấy hoàn thành xong công việc.\n- Việc cô ấy “hoàn thành công” việc xảy ra trước. => cô ấy “rời đi” xảy ra sau. \n=> “hoàn thành” chia quá khứ hoàn thành. \n=> “rời đi” chia thì quá khứ đơn.","options":{"A":"hadn’t left - finish","B":"don’t leave - had finished","C":"didn’t leave - had finished","D":"wasn’t leaving - finished"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/27","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":26,"question_number":27,"question_type":"choice","question_text":"The teacher asked the boy why he_____his homework.","answer":"D","explanation":"* Dịch nghĩa: Giáo viên đã hỏi tại sao anh ấy chưa hoàn thành bài tập về nhà.\n-Việc anh ấy chưa hoàn thành bài tập về nhà xảy ra trước hành động “giáo viên hỏi”.\n=> chia thì quá khứ hoàn thành.","options":{"A":"have done","B":"did","C":"have been doing","D":"hadn’t done"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/28","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":27,"question_number":28,"question_type":"choice","question_text":"She_____the letter when she_____she_____it to the wrong address.","answer":"B","explanation":"Dịch: Cô ấy gửi thư đi rồi thì cô ấy mới nhận ra là mình đã gửi nhầm địa chỉ. \n=> Có 3 hành động: gửi thư - nhận ra - gửi nhầm. Trong đó hành động nhận ra xảy ra sau nên chia quá khứ đơn, hành động gửi thử và gửi nhầm địa chỉ xảy ra trước nên chia quá khứ hoàn thành.","options":{"A":"posted - had realized - sent","B":"had posted - realized - had sent","C":"was posting - realized - had sent","D":"have posted - had realized - had sent"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/29","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":28,"question_number":29,"question_type":"choice","question_text":"Hardly_____a mile when it had a flat tyre.","answer":"A","explanation":"Căn cứ vào: cấu trúc đảo ngữ: Hardly + had + S + V (quá khứ phân từ) when + S + V (quá khứ đơn).\u000b- Dịch nghĩa: Xe ô tô mới đi được một dặm thì nó bị bục lốp.","options":{"A":"had the car gone","B":"did the car go","C":"had the car go","D":"do the car go"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/30","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":29,"question_number":30,"question_type":"choice","question_text":"The weather_____far worse than we_____.","answer":"D","explanation":"Dịch nghĩa: Thời tiết tệ hơn nhiều so với những gì chúng tôi đã dự tính.\n- Việc “dự đoán” xảy ra trước. => chia thì quá khứ hoàn thành.\n- “Thời tiết xấu hơn” dự đoán xảy ra sau. => chia thì quá khứ đơn.","options":{"A":"is - have expected","B":"was - was expected","C":"was - have been expecting","D":"was - had expected"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/31","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":30,"question_number":31,"question_type":"choice","question_text":"They_____for five years when they finally had a child.","answer":"B","explanation":"Dịch: Khi họ có con, họ đã cưới nhau được 5 năm rồi.\n=> Việc lấy nhau xảy ra trước hành động có con => trước của quá khứ ta chia quá khứ hoàn thành. \n*Note: Be married = get married (a): kết hôn, cưới","options":{"A":"will have been married","B":"had been married","C":"have married","D":"will be marrying"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/32","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":31,"question_number":32,"question_type":"choice","question_text":"When she_____her work, she_____to the cinema.","answer":"C","explanation":"* Dịch nghĩa: Khi cô ấy hoàn thành xong công việc, cô ấy đã đi đến rạp chiếu phim.\n- Hoàn thành công việc xảy ra trước. => chia thì quá khứ hoàn thành.\n- Đến rạp chiếu phim xảy ra sau. => chia thì quá khứ đơn.","options":{"A":"finished - had gone","B":"was finishing - had been going","C":"had finished - went","D":"had been finishing - was going"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/33","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":32,"question_number":33,"question_type":"choice","question_text":"At the time of our first meeting there was a considerable difference between me and him; he_____articles in magazines for over five years while I was practically unknown.","answer":"A","explanation":"Dịch nghĩa: Vào thời điểm cuộc gặp đầu tiên của chúng tôi, có một sự khác biệt lớn giữa tôi và anh ấy. Anh ấy đã có vài bài báo được đăng trên các tạp chí trong khoảng 5 năm trong khi tôi gần như chả có ai biết đến. \n=> Anh ấy đã có bài được đăng báo trong suốt 5 năm và từ trước khi chúng tôi gặp nhau. \n=> Hành động diễn ra trước thời điểm quá khứ và nhấn mạnh tính tiếp diễn nên ta chia thì quá khứ hoàn thành tiếp diễn.","options":{"A":"had been publishing","B":"was publishing","C":"has been publishing","D":"published"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/34","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":33,"question_number":34,"question_type":"choice","question_text":"The house_____to the ground by the time the firemen_____","answer":"B","explanation":"Dịch nghĩa: Vào thời điểm lính cứu hỏa đến, ngôi nhà đã cháy lan ra mặt đất.\n=> Việc “ngôi nhà cháy lan ra mặt đất” xảy ra trước. => chia thì quá khứ hoàn thành.\n=> “Lính cứu hỏa đến” xảy ra sau. => chia thì quá khứ đơn.\nCấu trúc:\n                               By the time + S + V(quá khứ đơn), S + V (quá khứ hoàn thành)","options":{"A":"burned - had arrived","B":"had burned - arrived","C":"was burning – arrived","D":"burned - was arriving"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/35","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":34,"question_number":35,"question_type":"choice","question_text":"I_____the accident when I was waiting for the taxi.","answer":"A","explanation":"* Căn cứ vào:\n- Khi diễn tả một hành động đang xảy ra trong quá khứ thì có một hành động khác xen vào.\n=> Hành động xen vào chia thì quá khứ đơn. \n=> Việc “nhìn thấy” là hành động xen vào nên chia thì quá khứ đơn. \u000b* Dịch nghĩa: Tôi đã nhìn thấy một vụ tai nạn khi tôi đang chờ xe taxi.","options":{"A":"saw","B":"was seeing","C":"had been seeing","D":"have seen"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/36","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":35,"question_number":36,"question_type":"choice","question_text":"I agree that while the soup was OK, the meat was too dry - we_____ it about 20 minutes too long.","answer":"A","explanation":"Căn cứ vào “too long” - quá lâu (một quá trình) nên động từ trong mệnh đề này chia ở thì hoàn thành. Từ đó, ta loại phương án B. \n- Căn cứ vào động từ ở mệnh đề trước “was” chia thì quá khứ đơn nên vế sau chia thì quá khứ hoàn thành (theo quy tắc về sự phối thì.)\nTạm dịch: Mình đồng ý là trong khi món súp ngon thì món thịt lại quá khô - chúng ta đã nướng nó trong khoảng 20 phút liền.","options":{"A":"had roasted","B":"roast","C":"had roast","D":"have been roasting"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/37","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":36,"question_number":37,"question_type":"choice","question_text":"At this time last night while people were talking to each other, he_____his book.","answer":"A","explanation":"* Căn cứ vào:\n- at this time last night: là dấu hiệu nhận biết thì quá khứ tiếp diễn.\n* Dịch nghĩa: Vào thời điểm này tối qua trong khi mọi người đang nói chuyện với nhau, anh ấy đang đọc sách.","options":{"A":"was reading","B":"is reading","C":"have read","D":"reads"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/38","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":37,"question_number":38,"question_type":"choice","question_text":"While we_____in the park, Mary fell over.","answer":"D","explanation":"* Căn cứ cách dùng của thì quá khứ tiếp diễn:\n- Diễn tả hành động đang xảy ra thì có hành động khác xen vào.\n* Dịch nghĩa: Trong khi chúng tôi đang chạy ở công viên, Mary đã bị ngã.\n=> hành động “chạy” chia thì quá khứ tiếp diễn.","options":{"A":"ran","B":"are running","C":"had been running","D":"were running"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/39","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":38,"question_number":39,"question_type":"choice","question_text":"_____I was listening to music, I heard the doorbell.","answer":"A","explanation":"Dịch: Khi tôi đang nghe nhạc, tôi nghe thấy tiếng chuông cửa.\nA. When: khi\nB. Why: tại sao\nC. If: nếu\nD. Because: bởi vì","options":{"A":"When","B":"While","C":"If","D":"Because"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/40","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":39,"question_number":40,"question_type":"choice","question_text":"How long_____English before she went to London?","answer":"B","explanation":"* Dịch nghĩa: Trước khi cô ấy đến London, cô ấy đã học tiếng anh trong bao lâu?\n=> Nhấn mạnh thời gian liên tục cô ấy học Tiếng Anh và xảy ra trước việc “cô ấy đến London”.\n=> Ta chia thì quá khứ hoàn thành tiếp diễn","options":{"A":"did she learn","B":"had she been learning","C":"have she learnt","D":"was she learning"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/41","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":40,"question_number":41,"question_type":"choice","question_text":"They_____at the station for 90 minutes when the train finally arrived.","answer":"C","explanation":"* Căn cứ cách dùng của thì QKHT tiếp diễn:\n- Nhấn mạnh một hành động xảy ra liên tục kéo dài trước hành động khác trong một hành động khác trong quá khứ.\n- “for 90 minutes” nhấn mạnh “việc họ phải chờ”, việc “chờ” diễn ra trước việc “tàu đến”.\n* Dịch nghĩa: Cuối cùng tàu  đã đến họ đã chờ 90 phút ở nhà ga.","options":{"A":"were waiting","B":"will be learning","C":"had been waiting","D":"are learning"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/42","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":41,"question_number":42,"question_type":"choice","question_text":"We_____for her ring for two hours and then we found it in the bathroom.","answer":"A","explanation":"Dịch: Chúng tôi đã tìm chiếc nhẫn của cô ấy trong hai giờ và sau đó chúng tôi đã tìm thấy nó ở trong phòng tắm.\n+ hành động \" tìm nhẫn của cô ấy\" xảy ra trong quá khứ, “tìm thấy nó ở phòng tắm” xảy ra sau.\n+ “for two hours” nhấn mạnh tính liên tục của hành động \" tìm nhẫn của cô ấy\", nó diễn ra liên tục trong hai giờ.\n=> Chia thì quá khứ hoàn thành tiếp diễn.","options":{"A":"had been looking","B":"were looking","C":"will be learning","D":"have been learning"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/43","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":42,"question_number":43,"question_type":"choice","question_text":"Frank Sinatra caught the flu because he_____in the rain too long.","answer":"D","explanation":"Dịch: Frank Sinatra đã bị cúm bởi vì anh ấy đã hát trong trời mưa quá lâu.\n+ \" hát\" là hành động xảy ra trong quá khứ và đã chấm dứt, \" hát\" xảy ra trước việc “bị cúm”.\n+ “too long”  nhấn mạnh đến tính liên tục của việc “hát” xảy trong trong khoảng thời gian “quá lâu”. \n=> Chia thì quá khứ hoàn thành tiếp diễn.","options":{"A":"was singing","B":"will be learning","C":"is singing","D":"had been singing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/44","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":43,"question_number":44,"question_type":"choice","question_text":"When police were investigating the road accident, they discovered that the driver_____two road accidents before.","answer":"A","explanation":"* Căn cứ vào cách dùng của thì quá khứ hoàn thành:\u000b- Nhấn mạnh hành động xảy ra trước hành động khác trong quá khứ.\u000b- Nhấn mạnh “Lái xe có liên quan đến hai vụ tai nạn trước đó”.\u000b* Dịch nghĩa: Khi cảnh sát đang điều tra vụ tai nạn giao thông, họ đã phát hiện ra rằng lái xe có liên quan đến hai vụ tai nạn giao thông trước đó.","options":{"A":"had been involved in","B":"had been being involved in","C":"will be involving in","D":"will have involved in"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/45","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":44,"question_number":45,"question_type":"choice","question_text":"They_____anyone while they were walking home because it was raining.","answer":"C","explanation":"* Căn cứ vào cách dùng của thì quá khứ đơn: diễn tả hành động xảy ra trong quá khứ. \n- “Họ đã không nhìn thấy” => chia thì quá khứ đơn. \n* Dịch nghĩa: Họ đã không nhìn thấy ai trong khi họ đang đi về nhà bởi vì trời mưa.","options":{"A":"weren’t seeing","B":"hadn’t see","C":"didn’t see","D":"weren’t seen"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/46","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":45,"question_number":46,"question_type":"choice","question_text":"Although at that time my knowledge of German was very poor, I _____most of what they said.","answer":"C","explanation":"Dịch: Mặc dù ở thời điểm đó vốn kiến thức về tiếng Đức của tôi rất kém, nhưng tôi vẫn cố gắng hiểu được hầu hết những gì họ nói.\nTa có cấu trúc: manage to do st: xoay sở để làm gì\nLưu ý: \nXét thì động từ thì ta thấy cả A và C đều đúng. Nhưng xét về nghĩa và ngữ cảnh của câu thì ta chọn C.","options":{"A":"understood","B":"have understood","C":"managed to understand","D":"didn’t understand"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/47","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":46,"question_number":47,"question_type":"choice","question_text":"We watched the film The Godfather last night. We had seen the film about 3 times before but we watched it again because John_____it.","answer":"B","explanation":"Dịch nghĩa: Chúng tôi đã xem bộ phim The Godfather tối qua. Chúng tôi đã xem bộ phim đó ba lần trước đây nhưng chúng tôi vẫn xem lại nó một lần nữa bởi vì Tom chưa bao giờ xem nó.\n=> Hành động chưa xem bao giờ của John là tính đến thời điểm tối qua nên chia thành thì quá khứ hoàn thành. Nếu chia hiện tại hoàn thành thì đồng nghĩa John đã xem một lần tối qua rồi chứ không phải chưa xem bao giờ => Trái với giả thiết","options":{"A":"had been seeing","B":"had never seen","C":"have never seen","D":"have been eating"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/48","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":47,"question_number":48,"question_type":"choice","question_text":"We_____for nearly 100 kilometres before we finally found a service station we could stop at.","answer":"C","explanation":"Căn cứ vào: “cách dùng của thì quá khứ hoàn thành”: Diễn tả một hành động xảy ra kéo dài trước một hành động khác trong quá khứ.\n=> Khi muốn nhấn mạnh tính liên tục (quá trình) của hành động trong ngữ cảnh đó, ta dùng thì quá khứ hoàn thành tiếp diễn:\u000b+ đã lái xe gần 100 km (hành động xảy ra trước và kéo dài liên tục)\u000b+ tìm một trạm xăng để dừng lại (hành động xảy ra sau).\u000b=> Đáp án A không sai nhưng đáp án C mới là phương án tối ưu nhất.\u000b- Dịch nghĩa: Chúng tôi đã lái xe gần 100 km trước khi chúng tôi tìm thấy một trạm xăng chúng tôi có thể dừng lại.","options":{"A":"had driven","B":"have been driving","C":"had been driving","D":"have driven"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/49","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":48,"question_number":49,"question_type":"choice","question_text":"I_____a student in Moloxop School in 1998.","answer":"A","explanation":"Căn cứ vào: “in + mốc thời gian trong quá khứ” => chia thì quá khứ đơn. \n- Dịch: Vào năm 1998 tôi là học sinh của trường Monoxop.","options":{"A":"was","B":"were","C":"to be","D":"to was"}},
{"id":"chuyen-de-thi-dong-tu/exercise/10/q/50","exercise_id":"chuyen-de-thi-dong-tu/exercise/10","position":49,"question_number":50,"question_type":"choice","question_text":"When I got home I realised that while I_____someone had stolen my wallet.","answer":"D","explanation":"Dịch nghĩa: Khi tôi về nhà, tôi nhận ra trong khi tôi đi bộ thì có ai đó đã lấy trộm ví của tôi. \n=> Việc đi bộ và bị mất trộm ví xảy ra trước hành động nhận ra nên chia quá khứ hoàn thành. Việc đi bộ là hành động tiếp diễn nên ta dùng quá khứ hoàn thành tiếp diễn để nhấn mạnh tính tiếp diễn.","options":{"A":"had walked","B":"have been walking","C":"have walked","D":"had been walking"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":0,"question_number":1,"question_type":"choice","question_text":"We_____to the hospital to visit Mike when he_____to say that he was fine.","answer":"C","explanation":"Dịch nghĩa: Chúng tôi đang đi đến bệnh viện để thăm Mike thì anh ấy gọi đến để nói rằng anh ấy vẫn ổn.\n+ “đang đi đến bệnh viện” là hành động đang xảy => chia quá khứ tiếp diễn.\n+  “gọi đến” là hành động xen vào  => chia thì quá khứ đơn.","options":{"A":"were driving - was calling","B":"drove - called","C":"were driving - called","D":"drove - was calling"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":1,"question_number":2,"question_type":"choice","question_text":"What_____to you on Sunday night?","answer":"B","explanation":"Dịch nghĩa: Chuyện gì đã xảy ra với bạn vào tối chủ nhật?\n+ hành động xảy ra và chấm dứt trong quá khứ => chia thì quá khứ đơn.","options":{"A":"happen","B":"happened","C":"was happening","D":"would happen"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":2,"question_number":3,"question_type":"choice","question_text":"Last night, we_____for you for ages but you never_____up.","answer":"A","explanation":"=> Key: A. waited – showed\u000b=> Vì: do cách dùng của thì quá khứ đơn: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ\u000b=> Dịch: Tối qua chúng tôi đã đợi bạn rất lâu nhưng bạn không đến.","options":{"A":"waited - showed","B":"would wait - showed","C":"were waiting - were showing","D":"waited - was showing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":3,"question_number":4,"question_type":"choice","question_text":"We_____our quality time when the unexpected guest_____.","answer":"B","explanation":"=> Key: B. were having – came\u000b=> Vì: diễn tả một hành động đang diễn ra thì một hành động khác xen vào\u000b=> Dịch: Chúng tôi đang có thời gian tuyệt vời với nhau thì vị khách không mời mà đến xuất hiện.","options":{"A":"had - came","B":"were having - came","C":"had been having - came","D":"have had - would have come"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":4,"question_number":5,"question_type":"choice","question_text":"Since they_____us they_____to visit us last Sunday, we_____forward to the day.","answer":"C","explanation":"Dịch nghĩa: Vì chủ nhật tuần trước họ bảo là họ sẽ đến thăm chúng tôi nên chúng tôi đã ngóng chờ ngày hôm đó. \n- Căn cứ vào trạng từ thời gian “last sunday” nên động từ “tell” phải chia về quá khứ đơn. Xét các đáp án chỉ có đáp án C phù hợp.","options":{"A":"were telling - came - looked","B":"would tell - would visit - would look","C":"told - would come - were looking","D":"tell - are coming - will look"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":5,"question_number":6,"question_type":"choice","question_text":"I_____out last night but at the last minute I_____that I had a quiz this morning","answer":"A","explanation":"=> Dịch: Tối qua tôi đang định ra ngoài nhưng vào phút cuối tôi nhận ra rằng mình có một bài kiểm tra sáng nay.\nGiải thích:  \n- căn cứ vào trạng từ last night nên động từ trong câu này phải chia ở thì quá khứ đơn. Từ đó, ta loại C,D.\n- thì tiếp diễn có thể dùng để diễn tả dự định\n=> Đáp án A","options":{"A":"was going - realized","B":"went - realized","C":"had gone - would realize","D":"would go — have realized"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":6,"question_number":7,"question_type":"choice","question_text":"She hasn't paid as much attention to her children as she_____ since she_____working.","answer":"B","explanation":"Dịch nghĩa: Cô ấy đã không chú ý nhiều đến bọn trẻ của mình như trước kể từ khi cô ấy bắt đầu đi làm. \n+ Ta có cấu trúc: S + V(hiện tại hoàn thành) + since + S + V(quá khứ đơn). \n=> Vế sau “since” chia thì quá khứ đơn\n+ Vị trí thứ nhất cần động từ để mang nghĩa “cô ấy từng làm”=> động từ phải chia ở quá khứ đơn; vì đang so sánh rằng “bây giờ không chú ý nhiều đến con cái như trước đây”. Khi không muốn nhắc lại cụm “pay attention to her children” nên họ đã dùng trợ động từ để thay thế là “did”.","options":{"A":"does - starts","B":"did - started","C":"was doing - was starting","D":"has done - would start"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":7,"question_number":8,"question_type":"choice","question_text":"My brother_____at the road when he_____into a hole.","answer":"C","explanation":"=> Key: C. wasn’t looking – fell\u000b=> Vì: một hành động đang diễn ra thì hành động khác xen vào\u000b=> Dịch: Khi anh trai tôi đang không nhìn đường thì anh ấy rơi xuống một cái hố.","options":{"A":"wasn't looking - was falling","B":"didn't look - has fallen","C":"wasn't looking - fell","D":"won't look - fall"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":8,"question_number":9,"question_type":"choice","question_text":"Magellan_____the first European who_____through the strait.","answer":"D","explanation":"=> Key: D. was – sailed\u000b=> Vì: theo cách dùng của thì quá khứ đơn: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ\u000b=> Dịch: Magellan là người châu Âu đầu tiên đi thuyền qua eo biển","options":{"A":"was - was sailing","B":"was being - was sailing","C":"had been - sailed","D":"was - sailed"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":9,"question_number":10,"question_type":"choice","question_text":"The first self-sufficient village in Britain_____the Norman's idea. They were some strange invaders who_____to change the country in a better way.","answer":"A","explanation":"=> Key: A. was – hoped\u000b=> Vì: theo cách dùng của thì quá khứ đơn: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ\u000b=> Dịch: Ngôi làng độc lập đầu tiên ở Anh là ý tưởng của người Norman. Họ là những kẻ xâm lược kỳ lạ đã hy vọng thay đổi đất nước theo cách tốt hơn.","options":{"A":"was - hoped","B":"is - have hoped","C":"have been - were hoping","D":"was being - had hoped"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/11","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":10,"question_number":11,"question_type":"choice","question_text":"Linda only_____the film after she_____the book.","answer":"B","explanation":"=> Vì: theo cách dùng của thì quá khứ đơn: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ và quá khứ hoàn thành để diển tả một sự việc đã xảy ra trước một sự việc khác trong quá khứ\u000b=> Dịch: Linda chỉ hiểu bộ phim sau khi cô đọc cuốn sách.","options":{"A":"understood - read","B":"understood - had read","C":"had understood - read","D":"understood - was reading"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/12","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":11,"question_number":12,"question_type":"choice","question_text":"_____you ever_____on TV before you_____in this reality show?","answer":"A","explanation":"=> Key: A. Had … appeared – took part\u000b=> Vì: quá khứ hoàn thành để diển tả một sự việc đã xảy ra trước một sự việc trong quá khứ và theo cách dùng của thì quá khứ đơn: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ\u000b=> Dịch: Bạn đã từng xuất hiện trên TV trước khi bạn tham gia chương trình thực tế này chưa?","options":{"A":"Had ... appeared - took part","B":"Have ... appeared - took part","C":"Did ... appear - had taken part","D":"Would ... appear - took part"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/13","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":12,"question_number":13,"question_type":"choice","question_text":"I wasn't sure how Belinda would react because I_____her long.","answer":"D","explanation":"Tạm dịch: Tôi không chắc là Belinda sẽ phản ứng như thế nào bởi vì tôi đã không hay biết gì về cô ấy từ rất lâu rồi. \n=> Căn cứ vào “long” nên mệnh đề sau chia thì hiện tại hoàn thành. Tuy nhiên, động từ ở mệnh đề trước chia thì quá khứ đơn nên động từ ở mệnh đề sau phải lùi một thì => thì quá khứ hoàn thành","options":{"A":"didn't know","B":"wasn't knowing","C":"hadn't been knowing","D":"hadn't known"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/14","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":13,"question_number":14,"question_type":"choice","question_text":"I wanted to say goodbye to Jerry, but he_____.","answer":"D","explanation":"=> Key: D. had already left\u000b=> Vì: dùng từ hiện tại do ở đây việc anh ta rời đi đã xảy ra trước việc nói tạm biệt\u000b=> Dịch: Tôi muốn nói lời tạm biệt với Jerry, nhưng anh ấy đã rời đi rồi","options":{"A":"was already left","B":"already left","C":"had already been leaving","D":"had already left"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/15","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":14,"question_number":15,"question_type":"choice","question_text":"When we_____to the airport, I realized that I_____my passport at home.","answer":"A","explanation":"=> Vì: việc quên hộ chiếu diễn ra trước việc đi tới sân bay, nên ta chia thì quá khứ đơn cho hành động “đến sân bay” và quá khứ hoàn thành cho hành động “quên hộ chiếu” - vì dùng để nó diễn tả một hành động xảy ra trước một hành động khác trong quá khứ.\u000b=> Dịch: Khi chúng tôi tới sân bay, tôi nhận ra là tôi đã quên hộ chiếu ở nhà.","options":{"A":"got - had left","B":"got - was left","C":"got - left","D":"had got - had left"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/16","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":15,"question_number":16,"question_type":"choice","question_text":"He_____the umbrella in his right hand trying to keep his balance.","answer":"B","explanation":"=> Vì: diễn tả một sự việc đã diễn ra và kết thúc trong quá khứ vì câu có hàm nghĩa thiên về cau kể => quá khứ đơn\u000b=> Dịch: Anh cầm chiếc ô trong tay phải cố giữ thăng bằng.","options":{"A":"hold","B":"held","C":"has been holding","D":"has held"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/17","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":16,"question_number":17,"question_type":"choice","question_text":"When I met Walters about two years before his death he didn't seem satisfied. He_____no major book since he settled in Uganda.","answer":"D","explanation":"Dịch nghĩa: Khi tôi gặp Walters khoảng hai năm trước khi ông ấy qua đời, ông ấy có vẻ không hài lòng. Ông đã không xuất bản cuốn sách lớn nào kể từ khi ông ấy định cư ở Uganda.\u000bTa có cấu trúc: Trước since chia hiện tại hoàn thành sau since chia quá khứ đơn. Tuy nhiên, căn cứ vào các động từ \"met“, ”didn’t seem\" và quy tắc về sự phối thì nên ta chia động từ trong vị trí trống ở thì quá khứ hoàn thành.","options":{"A":"has published","B":"could have published","C":"published","D":"had published"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/18","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":17,"question_number":18,"question_type":"choice","question_text":"Throughout the campaign we_____our candidate's photographs on the walls of public buildings, hoping to attract women's votes.","answer":"C","explanation":"Dịch: Trong suốt chiến dịch đó, chúng tôi đã treo các bức ảnh của ứng cử viên của chúng tôi trên tường của các tòa nhà công cộng, với hy vọng thu hút phiếu bầu của phụ nữ. \n=> Hành động đã xảy ra và đã kết thúc trong quá khứ ta chia thì quá khứ đơn. Mặc dù không có thời gian hay dấu hiệu thời gian cụ thể, nhưng căn cứ vào ngữ nghĩa câu, có thể thấy đó là một câu kể, nên tốt nhất vẫn hiểu nó là hành động đã diễn ra và kết thúc trong quá khứ thay vì ở thì hiện tại.","options":{"A":"have been hanging","B":"hanged","C":"hung","D":"have hung"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/19","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":18,"question_number":19,"question_type":"choice","question_text":"Many of the people who attended Major Gordon's funeral_____him for many years.","answer":"D","explanation":"Dịch nghĩa: Nhiều người đã tham dự đám tang của Thiếu tá Gordon đã không gặp ông trong nhiều năm.\u000b+ sự việc “không gặp Thiếu Tá” đã xảy ra trước việc “tham dự đám tang” => chia thì quá khứ hoàn thành.","options":{"A":"didn't see","B":"wouldn't see","C":"haven't seen","D":"hadn't seen"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/20","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":19,"question_number":20,"question_type":"choice","question_text":"Seeing Peter's handwriting on the envelope, she_____the letter without reading it. She has not mentioned it ever since.","answer":"B","explanation":"Dịch nghĩa: Nhìn thấy chữ viết tay của Peter trên phong bì, cô xé đã lá thư mà không đọc nó. Cô đã không đề cập đến nó kể từ đó.\u000b- Giải thích: Nhìn thấy chữ viết tay của Peter là xé thư ngay => hành động xảy ra nối tiếp nhau trong quá khứ => chia thì quá khứ đơn.","options":{"A":"was tearing","B":"tore","C":"had tom","D":"has tom"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/21","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":20,"question_number":21,"question_type":"choice","question_text":"We were both very excited about the visit, as we_____each other for ages.","answer":"C","explanation":"Dịch nghĩa: Cả hai chúng tôi đều rất hào hứng về chuyến viếng thăm, vì chúng tôi đã không gặp nhau lâu lắm rồi.\u000b+ “không gặp trong nhiều năm” là hành động xảy ra trước => chia thì quá khứ hoàn thành.","options":{"A":"never saw","B":"didn't see","C":"hadn't seen","D":"haven't seen"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/22","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":21,"question_number":22,"question_type":"choice","question_text":"What made you think he_____in the Royal Air Force?","answer":"B","explanation":"Căn cứ vào cách sử dụng của thì quá khứ hoàn thành: diễn tả hành động xảy ra trước hành động khác trong quá khứ.\u000b- Dịch nghĩa: Điều gì khiến bạn nghĩ rằng anh ấy đã ở trong Không quân Hoàng gia?\u000b+ Hành động “ở” xảy ra trước => chia thì quá khứ hoàn thành.","options":{"A":"must have to be","B":"had been","C":"was being","D":"had had to be"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/23","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":22,"question_number":23,"question_type":"choice","question_text":"Without turning my head in the direction of the gate I_____a small object just under the fence.","answer":"A","explanation":"Dịch nghĩa: Tôi phát hiện ra một vật nhỏ ngay dưới hàng rào mà không quay đầu mình về hướng cổng.\u000bGiai thích: \n- Căn cứ theo ngữ cảnh của câu => câu chia ở thể chủ động => D sai\n- Hành động “phát hiện một vật nhỏ” xảy ra và đã kết thúc trong quá khứ => chia ở thì quá khứ đơn","options":{"A":"spotted","B":"had spotted","C":"have spotted","D":"was spotted"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/24","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":23,"question_number":24,"question_type":"choice","question_text":"With just one exception, the report says, each of the trees that was cut down_____very expensive treatment for periods of up to ten years.","answer":"D","explanation":"Dịch nghĩa: Chỉ có một ngoại lệ, báo cáo cho biết, mỗi cây bị chặt hạ đã trải qua quá trình chăm sóc rất tốn kém trong thời gian lên tới mười năm.\n=> Vì hành động \"bị chặt\" chia quá khứ đơn => Việc “trải qua quá trình chăm sóc” diễn ra trước hành động “bị chặt” => hành động \"trải qua quá trình chăm sóc\" phải chia thì quá khứ hoàn thành.","options":{"A":"had to be undergone","B":"was undergone","C":"has undergone","D":"had undergone"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/25","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":24,"question_number":25,"question_type":"choice","question_text":"They_____married for two years or so when Roy enployed a very attractive Indian secretary in his Glasgow office.","answer":"D","explanation":"Dịch nghĩa: Họ chỉ mới kết hôn được hai năm hoặc lâu hơn thì Roy tuyển dụng một thư ký Ấn Độ rất hấp dẫn trong văn phòng tại thành phố Glasgow của ông.\u000b+ “việc kết hôn” xảy ra trước sự việc “Roy được thuê” => chia thì quá khứ hoàn thành.","options":{"A":"only have been","B":"were only","C":"have only been","D":"had only been"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/26","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":25,"question_number":26,"question_type":"choice","question_text":"I know too little Dutch to have understood what they were talking about. What I_____was that their boss would be there the next morning.","answer":"A","explanation":"Dịch nghĩa: Tôi biết quá ít về tiếng Hà Lan để hiểu những gì họ đang nói. Điều tôi đã hiểu là ông chủ của họ sẽ ở đó vào sáng hôm sau.\u000bCăn cứ: diễn tả hành động xảy ra và kết thúc trong quá khứ.","options":{"A":"understood","B":"didn't understand","C":"have understood","D":"could have understood"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/27","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":26,"question_number":27,"question_type":"choice","question_text":"The driver_____violently and managed to stop the car just inches from the body lying on the road.","answer":"C","explanation":"Dịch nghĩa: Người lái xe đã phanh gấp và cố gắng dừng chiếc xe chỉ cách cơ thể nằm trên đường vài inch.\u000b+ “Phanh gấp => cố gắng để dừng lại” là những hành động xảy ra liên tiếp trong quá khứ => chia thì quá khứ đơn.","options":{"A":"was braking","B":"has braked","C":"braked","D":"had braked"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/28","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":27,"question_number":28,"question_type":"choice","question_text":"They stopped to take a rest because they_____long enough.","answer":"B","explanation":"+ Hành động \"làm việc\"  kéo dài liên tục, xảy ra trước hành động \"dừng lại để nghỉ\".\n=> chia thì quá khứ hoàn thành tiếp diễn. \n- Dịch nghĩa: Họ đã dừng lại để nghỉ ngơi bởi trước đó họ đã làm việc liên tục đủ lâu rồi.","options":{"A":"have worked","B":"had been working","C":"worked","D":"were working"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/29","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":28,"question_number":29,"question_type":"choice","question_text":"The performance_____at 7 o'clock and_____for three hours. We all_____it.","answer":"C","explanation":"Căn cứ: cách dùng của thì quá khứ đơn: kể lại những hành động xảy ra liên tiếp trong quá khứ.\u000b- Dịch nghĩa: Buổi biểu diễn bắt đầu lúc 7 giờ và kéo dài trong ba tiếng. Tất cả chúng tôi đều thích nó.","options":{"A":"had begun/lasted/enjoyed","B":"began/had lasted/enjoyed","C":"began/lasted/enjoyed","D":"began/lasted/enjoy"}},
{"id":"chuyen-de-thi-dong-tu/exercise/11/q/30","exercise_id":"chuyen-de-thi-dong-tu/exercise/11","position":29,"question_number":30,"question_type":"choice","question_text":"By the time you_____cooking, they had done their homework.","answer":"A","explanation":"Căn cứ vào cấu trúc: By the time + S(quá khứ đơn), S + V(quá khứ hoàn thành).\u000b- Dịch nghĩa: Vào thời điểm bạn nấu ăn xong, họ đã hoàn thành xong bài tập về nhà.","options":{"A":"finished","B":"had finished","C":"finish","D":"were finishing"}},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/1","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":0,"question_number":1,"question_type":"fill","question_text":"He_____(help) her take care of her children tomorrow morning.","answer":"will get","explanation":"Dự đoán tương lai hoặc hứa hẹn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/2","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":1,"question_number":2,"question_type":"fill","question_text":"She_____(bring) you a cup of tea soon.","answer":"will lend","explanation":"Quyết định ngay tại thời điểm nói.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/3","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":2,"question_number":3,"question_type":"fill","question_text":"She hopes that Mary_____(come) to the party tonight.","answer":"will help","explanation":"Lời đề nghị giúp đỡ tại thời điểm nói.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/4","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":3,"question_number":4,"question_type":"fill","question_text":"If you don’t study hard, you_____(not pass) the final exam.","answer":"will open","explanation":"Quyết định làm gì đó ngay lập tức.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/5","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":4,"question_number":5,"question_type":"fill","question_text":"- Where you_____(be) this time next year? - I_____(be) in Japan.","answer":"will show","explanation":"Lời hứa sẽ chỉ dẫn.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/6","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":5,"question_number":6,"question_type":"fill","question_text":"They_____(visit) China next week.","answer":"will answer","explanation":"Quyết định trả lời điện thoại ngay lập tức.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/7","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":6,"question_number":7,"question_type":"fill","question_text":"You look tired, so I_____(bring) you something to eat.","answer":"will love","explanation":"Dự đoán cảm xúc của đối phương.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/8","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":7,"question_number":8,"question_type":"fill","question_text":"In that case, I_____(buy) a coffee as a token of gratitude.","answer":"will phone","explanation":"Lời hứa sẽ gọi điện khi đến nơi.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/9","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":8,"question_number":9,"question_type":"fill","question_text":"I can’t meet you this evening. A friend of mine_____(come) to see me.","answer":"will do","explanation":"Lời hứa sẽ tự làm.","options":null},
{"id":"chuyen-de-thi-dong-tu/exercise/12/q/10","exercise_id":"chuyen-de-thi-dong-tu/exercise/12","position":9,"question_number":10,"question_type":"fill","question_text":"Don’t worry about your exam. I sure you_____(pass).","answer":"will pay","explanation":"Quyết định trả tiền nước ngay lập tức.","options":null},
